INSERT INTO compiled_contracts (id, created_at, updated_at, created_by, updated_by, compiler, version, language, name, fully_qualified_name, compiler_settings, compilation_artifacts, creation_code_hash, creation_code_artifacts, runtime_code_hash, runtime_code_artifacts, additional_input) VALUES ('3b889382-a890-4269-80d9-fcdcce64deba', '2024-08-08 10:05:07.810713+00', '2024-08-08 10:05:07.810713+00', 'sourcify', 'sourcify', 'solc', '0.8.9+commit.e5eed63a', 'solidity', 'TransparentUpgradeableProxy', '@openzeppelin/contracts/proxy/transparent/TransparentUpgradeableProxy.sol:TransparentUpgradeableProxy', '{"metadata": {"bytecodeHash": "ipfs"}, "libraries": {}, "optimizer": {"runs": 200, "enabled": true}, "evmVersion": "london", "remappings": []}', '{"abi": [{"type": "constructor", "inputs": [{"name": "_logic", "type": "address", "internalType": "address"}, {"name": "admin_", "type": "address", "internalType": "address"}, {"name": "_data", "type": "bytes", "internalType": "bytes"}], "stateMutability": "payable"}, {"name": "AdminChanged", "type": "event", "inputs": [{"name": "previousAdmin", "type": "address", "indexed": false, "internalType": "address"}, {"name": "newAdmin", "type": "address", "indexed": false, "internalType": "address"}], "anonymous": false}, {"name": "BeaconUpgraded", "type": "event", "inputs": [{"name": "beacon", "type": "address", "indexed": true, "internalType": "address"}], "anonymous": false}, {"name": "Upgraded", "type": "event", "inputs": [{"name": "implementation", "type": "address", "indexed": true, "internalType": "address"}], "anonymous": false}, {"type": "fallback", "stateMutability": "payable"}, {"name": "admin", "type": "function", "inputs": [], "outputs": [{"name": "admin_", "type": "address", "internalType": "address"}], "stateMutability": "nonpayable"}, {"name": "changeAdmin", "type": "function", "inputs": [{"name": "newAdmin", "type": "address", "internalType": "address"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "implementation", "type": "function", "inputs": [], "outputs": [{"name": "implementation_", "type": "address", "internalType": "address"}], "stateMutability": "nonpayable"}, {"name": "upgradeTo", "type": "function", "inputs": [{"name": "newImplementation", "type": "address", "internalType": "address"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "upgradeToAndCall", "type": "function", "inputs": [{"name": "newImplementation", "type": "address", "internalType": "address"}, {"name": "data", "type": "bytes", "internalType": "bytes"}], "outputs": [], "stateMutability": "payable"}, {"type": "receive", "stateMutability": "payable"}], "devdoc": {"kind": "dev", "details": "This contract implements a proxy that is upgradeable by an admin. To avoid https://medium.com/nomic-labs-blog/malicious-backdoors-in-ethereum-proxies-62629adf3357[proxy selector clashing], which can potentially be used in an attack, this contract uses the https://blog.openzeppelin.com/the-transparent-proxy-pattern/[transparent proxy pattern]. This pattern implies two things that go hand in hand: 1. If any account other than the admin calls the proxy, the call will be forwarded to the implementation, even if that call matches one of the admin functions exposed by the proxy itself. 2. If the admin calls the proxy, it can access the admin functions, but its calls will never be forwarded to the implementation. If the admin tries to call a function on the implementation it will fail with an error that says \"admin cannot fallback to proxy target\". These properties mean that the admin account can only be used for admin actions like upgrading the proxy or changing the admin, so it''s best if it''s a dedicated account that is not used for anything else. This will avoid headaches due to sudden errors when trying to call a function from the proxy implementation. Our recommendation is for the dedicated account to be an instance of the {ProxyAdmin} contract. If set up this way, you should think of the `ProxyAdmin` instance as the real administrative interface of your proxy.", "methods": {"admin()": {"details": "Returns the current admin. NOTE: Only the admin can call this function. See {ProxyAdmin-getProxyAdmin}. TIP: To get this value clients can read directly from the storage slot shown below (specified by EIP1967) using the https://eth.wiki/json-rpc/API#eth_getstorageat[`eth_getStorageAt`] RPC call. `0xb53127684a568b3173ae13b9f8a6016e243e63b6e8ee1178d6a717850b5d6103`"}, "constructor": {"details": "Initializes an upgradeable proxy managed by `_admin`, backed by the implementation at `_logic`, and optionally initialized with `_data` as explained in {ERC1967Proxy-constructor}."}, "implementation()": {"details": "Returns the current implementation. NOTE: Only the admin can call this function. See {ProxyAdmin-getProxyImplementation}. TIP: To get this value clients can read directly from the storage slot shown below (specified by EIP1967) using the https://eth.wiki/json-rpc/API#eth_getstorageat[`eth_getStorageAt`] RPC call. `0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc`"}, "upgradeTo(address)": {"details": "Upgrade the implementation of the proxy. NOTE: Only the admin can call this function. See {ProxyAdmin-upgrade}."}, "changeAdmin(address)": {"details": "Changes the admin of the proxy. Emits an {AdminChanged} event. NOTE: Only the admin can call this function. See {ProxyAdmin-changeProxyAdmin}."}, "upgradeToAndCall(address,bytes)": {"details": "Upgrade the implementation of the proxy, and then call a function from the new implementation as specified by `data`, which should be an encoded function call. This is useful to initialize new storage variables in the proxied contract. NOTE: Only the admin can call this function. See {ProxyAdmin-upgradeAndCall}."}}, "version": 1}, "sources": {"@openzeppelin/contracts/proxy/Proxy.sol": {"id": 2}, "@openzeppelin/contracts/utils/Address.sol": {"id": 5}, "@openzeppelin/contracts/utils/StorageSlot.sol": {"id": 6}, "@openzeppelin/contracts/proxy/beacon/IBeacon.sol": {"id": 3}, "@openzeppelin/contracts/proxy/ERC1967/ERC1967Proxy.sol": {"id": 0}, "@openzeppelin/contracts/proxy/ERC1967/ERC1967Upgrade.sol": {"id": 1}, "@openzeppelin/contracts/proxy/transparent/TransparentUpgradeableProxy.sol": {"id": 4}}, "userdoc": {"kind": "user", "methods": {}, "version": 1}, "storageLayout": {"types": null, "storage": []}}', '\x5b877c6175a8c1ddd3f6c2cfae5840f556a2b21d30115f38bc478a7181d7fc97', '{"sourceMap": "1549:3526:4:-:0;;;1823:224;;;;;;;;;;;;;;;;;;:::i;:::-;1908:6;1916:5;984:54:0;1037:1;992:41;984:54;:::i;:::-;-1:-1:-1;;;;;;;;;;;952:87:0;945:95;;;;:::i;:::-;1050:39;1068:6;1076:5;1083;1050:17;:39::i;:::-;-1:-1:-1;1963:45:4::1;::::0;-1:-1:-1;2007:1:4::1;1971:32;1963:45;:::i;:::-;-1:-1:-1::0;;;;;;;;;;;1940:69:4::1;1933:77;;;;:::i;:::-;2020:20;2033:6:::0;2020:12:::1;:20::i;:::-;1823:224:::0;;;1549:3526;;2054:315:1;2162:37;2181:17;2162:18;:37::i;:::-;2214:27;;-1:-1:-1;;;;;2214:27:1;;;;;;;;2269:1;2255:4;:11;:15;:28;;;;2274:9;2255:28;2251:112;;;2299:53;2328:17;2347:4;2299:28;;;;;:53;;:::i;:::-;;2251:112;2054:315;;;:::o;5493:135::-;5557:35;5570:11;:9;:11::i;:::-;5557:35;;;-1:-1:-1;;;;;2238:15:7;;;2220:34;;2290:15;;;2285:2;2270:18;;2263:43;2155:18;5557:35:1;;;;;;;5602:19;5612:8;5602:9;:19::i;:::-;5493:135;:::o;1403:259::-;1484:37;1503:17;1484:18;;;;;:37;;:::i;:::-;1476:95;;;;-1:-1:-1;;;1476:95:1;;2519:2:7;1476:95:1;;;2501:21:7;2558:2;2538:18;;;2531:30;2597:34;2577:18;;;2570:62;-1:-1:-1;;;2648:18:7;;;2641:43;2701:19;;1476:95:1;;;;;;;;;1638:17;1581:48;-1:-1:-1;;;;;;;;;;;1608:20:1;;1581:26;;;;;:48;;:::i;:::-;:74;;-1:-1:-1;;;;;;1581:74:1;-1:-1:-1;;;;;1581:74:1;;;;;;;;;;-1:-1:-1;1403:259:1:o;6276:198:5:-;6359:12;6390:77;6411:6;6419:4;6390:77;;;;;;;;;;;;;;;;;:20;:77::i;:::-;6383:84;6276:198;-1:-1:-1;;;6276:198:5:o;4977:122:1:-;5021:7;5047:39;-1:-1:-1;;;;;;;;;;;5074:11:1;;5047:26;;;;;:39;;:::i;:::-;:45;-1:-1:-1;;;;;5047:45:1;;4977:122;-1:-1:-1;4977:122:1:o;5181:201::-;-1:-1:-1;;;;;5244:22:1;;5236:73