ype": "function", "inputs": [{"name": "_fulfiller", "type": "address", "internalType": "address"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "setMigrationAddress", "type": "function", "inputs": [{"name": "_destination", "type": "address", "internalType": "address"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "setUserAllowedMarketplaces", "type": "function", "inputs": [{"name": "guardEnabled", "type": "bool", "internalType": "bool"}, {"name": "marketplaceAllowed", "type": "bool", "internalType": "bool"}, {"name": "marketplaces", "type": "address[]", "internalType": "address[]"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "setUserAllowedNfts", "type": "function", "inputs": [{"name": "guardEnabled", "type": "bool", "internalType": "bool"}, {"name": "nftAllowed", "type": "bool", "internalType": "bool"}, {"name": "nfts", "type": "address[]", "internalType": "address[]"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "setUserIsPaused", "type": "function", "inputs": [{"name": "isPaused", "type": "bool", "internalType": "bool"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "setUserMaxTip", "type": "function", "inputs": [{"name": "maxTipInWei", "type": "uint72", "internalType": "uint72"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "sniperBalances", "type": "function", "inputs": [{"name": "", "type": "address", "internalType": "address"}], "outputs": [{"name": "", "type": "uint256", "internalType": "uint256"}], "stateMutability": "view"}, {"name": "sniperGuardrails", "type": "function", "inputs": [{"name": "", "type": "address", "internalType": "address"}], "outputs": [{"name": "marketplaceGuardEnabled", "type": "bool", "internalType": "bool"}, {"name": "nftContractGuardEnabled", "type": "bool", "internalType": "bool"}, {"name": "isPaused", "type": "bool", "internalType": "bool"}, {"name": "maxTip", "type": "uint72", "internalType": "uint72"}], "stateMutability": "view"}, {"name": "solSnatch", "type": "function", "inputs": [{"name": "contractAddresses", "type": "address[]", "internalType": "address[]"}, {"name": "calls", "type": "bytes[]", "internalType": "bytes[]"}, {"name": "values", "type": "uint256[]", "internalType": "uint256[]"}, {"name": "sniper", "type": "address", "internalType": "address"}, {"name": "validatorTip", "type": "uint256", "internalType": "uint256"}, {"name": "fulfillerTip", "type": "uint256", "internalType": "uint256"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "supportsInterface", "type": "function", "inputs": [{"name": "interfaceId", "type": "bytes4", "internalType": "bytes4"}], "outputs": [{"name": "", "type": "bool", "internalType": "bool"}], "stateMutability": "view"}, {"name": "transferOwnership", "type": "function", "inputs": [{"name": "newOwner", "type": "address", "internalType": "address"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "withdraw", "type": "function", "inputs": [{"name": "amount", "type": "uint256", "internalType": "uint256"}], "outputs": [], "stateMutability": "nonpayable"}, {"type": "receive", "stateMutability": "payable"}], "devdoc": {"kind": "dev", "title": "AutoSniper 3.0 for @oSnipeNFT", "author": "0xQuit", "methods": {"depositSelf()": {"details": "deposit Ether into your own contract balance."}, "deposit(address)": {"params": {"sniper": "is the address who''s balance is affected."}, "details": "deposit Ether into the contract. "}, "migrateBalance()": {"details": "in the event of a future contract upgrade, this function allows snipers to easily move their ether balance to the new contract. This can only be called by the sniper to move their personal balance - the contract owner or anybody else does not have the power to migrate balances for users."}, "withdraw(uint256)": {"params": {"amount": "the amount of Ether to be withdrawn "}, "details": "withdraw Ether from your contract balance"}, "setUserMaxTip(uint72)": {"details": "Set up a maximum tip guardrail (in wei). If set to 0, guardrail will be disabled."}, "sendDirectTipToCoinbase()": {"details": "In cases where we execute a snipe without using this contract, use this function as a solution to bypass priority fee by tipping the coinbase directly."}, "setFulfillerAddress(address)": {"details": "Owner function to change fulfiller address if needed."}, "setMigrationAddress(address)": {"params": {"_destination": "the new AutoSniper version to allow migration to."}}, "configureMarkets(address[],bool)": {"details": "Owner function to set up global marketplace allowlist."}, "setUserAllowedNfts(bool,bool,address[])": {"params": {"nftAllowed": "boolean indicating whether the NFT contract is allowed or not", "guardEnabled": "if false then NFT contract allowlist will not be checked for this user"}, "details": "set up NFT contract allowlist"}, "setUserAllowedMarketplaces(bool,bool,address[])": {"params": {"guardEnabled": "if false then marketplace allowlist will not be checked for this user", "marketplaceAllowed": "boolean indicating whether the marketplace is allowed or not"}, "details": "set up a marketplace allowlist."}, "solSnatch(address[],bytes[],uint256[],address,uint256,uint256)": {"params": {"calls": "a matching array to contractAddresses, each index being a call to make to a given contract", "validatorTip": "the amount to send to block.coinbase. Reverts if this is 0.", "contractAddresses": "a list of contract addresses that will be called"}, "details": "solSnatch is a pure arbitrage function for fulfilling an order, and accepting a WETH offer in the same transaction. Contract balance can be used, but user balances cannot be affected - the call will revert if the post-call contract balance is lower than the pre-call balance."}, "fulfillOrder((uint8,uint72,uint72,uint72,address,address,address,uint256,bytes),(uint8,address,uint256,bytes)[],uint256)": {"params": {"claims": "an array of claims that the sniped NFT is eligible for. Claims are claimed and transferred to the sniper along with the sniped NFT.", "wethSubsidy": "the amount of WETH that needs to be converted."}, "details": "fulfillOrder conducts its own checks to ensure that the passed order is a valid sniper before forwarding the snipe on to the appropriate marketplace. Snipers can block orders by setting up guardrails that prevent orders from being fulfilled outside of allowlisted marketplaces or nft contracts, or with tips that exceed a maximum tip amount. WETH is used to subsidize the order in case the Sniper''s deposited balance is too low. WETH must be approved in order for this to work. Calculation is done off-chain and passed in via wethAmount. If for some reason there is an overpay, the marketplace will refund the difference, which is added to the Sniper''s balance."}, "fulfillNonCompliantMarketplaceOrder((uint8,uint72,uint72,uint72,address,address,address,uint256,bytes),(uint8,address,uint256,bytes)[],uint256)": {"params": {"claims": "an array of claims that the sniped NFT is eligible for. Claims are claimed and transferred to the sniper along with the sniped NFT.", "wethSubsidy": "the amount of WETH that needs to be converted."}, "details": "fulfillNonCompliantMarketplaceOrder is a variant on fulfillOrder, used for markets that don''t allow purchases through contracts. The fulfiller EOA will fulfill the order, and then use this function to get it to the sniper."}}, "version": 1}, "sources": {"src/AutoSniper.sol": {"id": 5}, "src/helpers/IPunk.sol": {"id": 6}, "src/helpers/IWETH.sol": {"id": 7}, "src/helpers/SniperEnums.sol": {"id": 8}, "src/helpers/SniperErrors.sol": {"id": 9}, "src/helpers/SniperStructs.sol": {"id": 10}, "lib/solmate/src/auth/Owned.sol": {"id": 4}, "lib/openzeppelin-contracts/contracts/token/ERC20/IERC20.sol": {"id": 1}, "lib/openzeppelin-contracts/contracts/token/ERC721/IERC721.sol": {"id": 2}, "lib/openzeppelin-contracts/contracts/token/ERC1155/IERC1155.sol": {"id": 0}, "lib/openzeppelin-contracts/contracts/utils/introspection/IERC165.sol": {"id": 3