ayable"}, {"name": "updateSwapTargets", "type": "function", "inputs": [{"name": "target", "type": "address", "internalType": "address"}, {"name": "add", "type": "bool", "internalType": "bool"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "withdrawEth", "type": "function", "inputs": [{"name": "to", "type": "address", "internalType": "address"}, {"name": "amount", "type": "uint256", "internalType": "uint256"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "withdrawToken", "type": "function", "inputs": [{"name": "token", "type": "address", "internalType": "address"}, {"name": "to", "type": "address", "internalType": "address"}, {"name": "amount", "type": "uint256", "internalType": "uint256"}], "outputs": [], "stateMutability": "nonpayable"}, {"type": "receive", "stateMutability": "payable"}], "devdoc": {"kind": "dev", "title": "Rainbow swap aggregator contract", "events": {"SwapTargetAdded(address)": {"details": "Event emitted when a swap target gets added"}, "SwapTargetRemoved(address)": {"details": "Event emitted when a swap target gets removed"}, "EthWithdrawn(address,uint256)": {"details": "Event emitted when ETH fees are withdrawn"}, "OwnerChanged(address,address)": {"details": "Event emitted when the owner changes"}, "TokenWithdrawn(address,address,uint256)": {"details": "Event emitted when token fees are withdrawn"}}, "methods": {"transferOwnership(address)": {"params": {"newOwner": "address of the new owner Can only be called by the current owner."}, "details": "Transfers ownership of the contract to a new account (`newOwner`)."}, "withdrawEth(address,uint256)": {"params": {"to": "address that''s receiving the ETH", "amount": "amount of ETH to withdraw"}, "details": "method to withdraw ETH (from the fees)"}, "updateSwapTargets(address,bool)": {"params": {"add": "flag to add or remove the swap target", "target": "address of the swap target to add"}, "details": "method to add or remove swap targets from swapTargets This is required so 