, "type": "function", "inputs": [], "outputs": [{"name": "", "type": "address", "internalType": "address"}], "stateMutability": "view"}, {"name": "getActiveHolderCount", "type": "function", "inputs": [], "outputs": [{"name": "", "type": "uint256", "internalType": "uint256"}], "stateMutability": "view"}, {"name": "getAllWithdrawals", "type": "function", "inputs": [], "outputs": [{"name": "", "type": "tuple[]", "components": [{"name": "to", "type": "address", "internalType": "address"}, {"name": "asset", "type": "address", "internalType": "address"}, {"name": "amt", "type": "uint256", "internalType": "uint256"}, {"name": "note", "type": "string", "internalType": "string"}], "internalType": "struct ExecutivePeerTreasury.Withdrawal[]"}], "stateMutability": "view"}, {"name": "getAvailableBalance", "type": "function", "inputs": [], "outputs": [{"name": "", "type": "uint256", "internalType": "uint256"}], "stateMutability": "view"}, {"name": "getClaimableAmount", "type": "function", "inputs": [{"name": "holder", "type": "address", "internalType": "address"}], "outputs": [{"name": "amount", "type": "uint256", "internalType": "uint256"}], "stateMutability": "view"}, {"name": "getEligibleSupply", "type": "function", "inputs": [], "outputs": [{"name": "eligibleSupply", "type": "uint256", "internalType": "uint256"}], "stateMutability": "view"}, {"name": "getPeerTreasuries", "type": "function", "inputs": [], "outputs": [{"name": "", "type": "tuple[]", "components": [{"name": "token", "type": "address", "internalType": "address"}, {"name": "totalReceived", "type": "uint256", "internalType": "uint256"}, {"name": "totalWithdrawn", "type": "uint256", "internalType": "uint256"}], "internalType": "struct ExecutivePeerTreasury.TreasurySnapshot[]"}], "stateMutability": "view"}, {"name": "getPeerTreasury", "type": "function", "inputs": [{"name": "token", "type": "address", "internalType": "address"}], "outputs": [{"name": "received", "type": "uint256", "internalType": "uint256"}, {"name": "withdrawn", "type": "uint256", "internalType": "uint256"}], "stateMutability": "view"}, {"name": "getPeerTreasuryETH", "type": "function", "inputs": [], "outputs": [{"name": "received", "type": "uint256", "internalType": "uint256"}, {"name": "withdrawn", "type": "uint256", "internalType": "uint256"}], "stateMutability": "view"}, {"name": "issueToken", "type": "function", "inputs": [], "outputs": [{"name": "", "type": "address", "internalType": "address"}], "stateMutability": "view"}, {"name": "issueTokenAddress", "type": "function", "inputs": [], "outputs": [{"name": "", "type": "address", "internalType": "address"}], "stateMutability": "view"}, {"name": "onTokenTransferUpdate", "type": "function", "inputs": [{"name": "from", "type": "address", "internalType": "address"}, {"name": "to", "type": "address", "internalType": "address"}, {"name": "value", "type": "uint256", "internalType": "uint256"}, {"name": "fromBalanceBefore", "type": "uint256", "internalType": "uint256"}, {"name": "toBalanceBefore", "type": "uint256", "internalType": "uint256"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "peerETHAvailable", "type": "function", "inputs": [], "outputs": [{"name": "", "type": "int256", "internalType": "int256"}], "stateMutability": "view"}, {"name": "peerTokenAvailable", "type": "function", "inputs": [{"name": "token", "type": "address", "internalType": "address"}], "outputs": [{"name": "", "type": "int256", "internalType": "int256"}], "stateMutability": "view"}, {"name": "peerTreasuryController", "type": "function", "inputs": [], "outputs": [{"name": "", "type": "address", "internalType": "address"}], "stateMutability": "view"}, {"name": "peerTreasuryNotifyReceived", "type": "function", "inputs": [{"name": "token", "type": "address", "internalType": "address"}, {"name": "amount", "type": "uint256", "internalType": "uint256"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "peerTreasuryReceiveETH", "type": "function", "inputs": [], "outputs": [], "stateMutability": "payable"}, {"name": "peerTreasuryReceiveTokens", "type": "function", "inputs": [{"name": "token", "type": "address", "internalType": "address"}, {"name": "amount", "type": "uint256", "internalType": "uint256"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "peerTreasuryTransferETH", "type": "function", "inputs": [{"name": "to", "type": "address", "internalType": "address payable"}, {"name": "amount", "type": "uint256", "internalType": "uint256"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "peerTreasuryTransferTokens", "type": "function", "inputs": [{"name": "token", "type": "address", "internalType": "address"}, {"name": "to", "type": "address", "internalType": "address"}, {"name": "amount", "type": "uint256", "internalType": "uint256"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "peerTreasuryTransferTokensDirect", "type": "function", "inputs": [{"name": "token", "type": "address", "internalType": "address"}, {"name": "to", "type": "address", "internalType": "address"}, {"name": "amount", "type": "uint256", "internalType": "uint256"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "previewDistribution", "type": "function", "inputs": [{"name": "totalAmount", "type": "uint256", "internalType": "uint256"}], "outputs": [{"name": "perTokenIncrease", "type": "uint256", "internalType": "uint256"}], "stateMutability": "view"}, {"name": "projectRevenueTreasury", "type": "function", "inputs": [], "outputs": [{"name": "", "type": "address", "internalType": "address"}], "stateMutability": "view"}, {"name": "receiveFee", "type": "function", "inputs": [], "outputs": [], "stateMutability": "payable"}, {"name": "rewardDebt", "type": "function", "inputs": [{"name": "", "type": "address", "internalType": "address"}], "outputs": [{"name": "", "type": "uint256", "internalType": "uint256"}], "stateMutability": "view"}, {"name": "setAutoDistributeThreshold", "type": "function", "inputs": [{"name": "minPayoutThreshold", "type": "uint256", "internalType": "uint256"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "setDistributionSupplyBasis", "type": "function", "inputs": [{"name": "newDistributionSupplyBasis", "type": "uint256", "internalType": "uint256"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "setProjectRevenueTreasury", "type": "function", "inputs": [{"name": "_projectRevenueTreasury", "type": "address", "internalType": "address"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "setStableCoinAddress", "type": "function", "inputs": [{"name": "newStableCoinAddress", "type": "address", "internalType": "address"}], "outputs": [], "stateMutability": "nonpayable"}, {"name": "stableCoinAddress", "type": "function", "inputs": [], "outputs": [{"name": "", "type": "address", "internalType": "address"}], "stateMutability": "view"}, {"name": "syncExcludedContracts", "type": "function", "inputs": [], "outputs": [], "stateMutability": "nonpayable"}, {"name": "totalOwedAmounts", "type": "function", "inputs": [], "outputs": [{"name": "", "type": "uint256", "internalType": "uint256"}], "stateMutability": "view"}], "devdoc": {"kind": "dev", "title": "IssueTokenDistributionManager", "errors": {"FailedInnerCall()": [{"details": "A call to an address target failed. The target may have reverted."}], "AddressEmptyCode(address)": [{"details": "There''s no code at `target` (it is not a contract)."}], "ReentrancyGuardReentrantCall()": [{"details": "Unauthorized reentrant call."}], "SafeERC20FailedOperation(address)": [{"details": "An operation with an ERC20 token failed."}], "AddressInsufficientBalance(address)": [{"details": "The ETH balance of the account is not enough to perform the operation."}], "SafeERC20FailedDecreaseAllowance(address,uint256,uint256)": [{"details": "Indicates a failed `decreaseAllowance` request."}]}, "details": "Called by IssueToken on every transfer to maintain holder registry      Distribution allocation requires TreasuryAdmin permission      Holders call claim() to collect their distributions (pay their own gas)  🎯 CLAIM-BASED MODEL: - TreasuryAdmin calls distributeToClaim() to allocate funds (O(1) gas!) - Holders call claim() to collect their proportional share (pays own gas) - Smart contracts CAN participate and handle their own receive() logic - No risk of malicious contracts blocking distributions  🚀 O(1) SCALABILITY: - Uses accumulatedPerToken global variable (scales to millions of holders) - rewardDebt pattern ensures transfers don''t retroactively change claims - Harvest-on-transfer locks in rewards at old balance before balance changes  Key Features: - PROPORTIONAL allocation: each holder receives (balance / totalSupply) * totalAmount - Tracks all-time holders array (never shrinks - gas optimization) - Maintains active holder count (decrements when balance → 0) - Uses token.balanceOf() as single source of truth (passed from token on transfers) - Protects owed distributions: totalOwedAmounts locked from admin withdrawal - Extends ExecutivePeerTreasury for admin controls + ReentrancyGuard", "methods": {"claim()": {"details": "Anyone can call to claim their own distributions      Uses rewardDebt pattern: owed = (balance * accumulatedPerToken) - rewardDebt      EOAs pay their own gas - they decide when it''s worth claiming      Smart contracts CAN claim too - they handle their own receive() logic", "returns": {"amount": "Amount claimed"}}, "constructor": {"params": {"_controller": "Controller address for permission checks", "_issueTokenAddress": "IssueToken address (only this token can report transfers)", "_distributionSupplyBasis": "Expected total supply for distribution calculations (0 = disabled, uses actual supply)", "_initialAutoDistributeThreshold": "Initial auto-distribute threshold (0 = disabled, >= 100 to enable)"}}, "receiveFee()": {"details": "ONLY for FeeManager → ProjectRevenueTreasury ETH fee distribution      Does NOT update totalReceived (reserved for peer-to-peer transfer accounting)      Does NOT emit events (gas optimization)      ⚠️ Use peerTreasuryReceiveETH() for tracked peer transfers that trigger downstream logic      ⚠️ NORMAL OPERATION: Funds received via this method are NOT auto-deployed         They accumulate in treasury balance until processRevenueAndDisperse() is called"}, "peerETHAvailable()": {"returns": {"_0": "The signed balance (can be negative if more was withdrawn than received - which is OK!) obviously the first lateral movement will be a withdrawal from a peerTreasury source"}}, "getEligibleSupply()": {"returns": {"eligibleSupply": "The circulating supply available for distributions"}}, "getAvailableBalance()": {"details": "Available = balanceOf(this) - totalOwedAmounts      This is what can be distributed or withdrawn by admin"}, "getActiveHolderCount()": {"details": "This is maintained automatically on every transfer      If deployed late, this will be 0 initially and build up as transfers occur"}, "syncExcludedContracts()": {"details": "Fetches all SmartContract entities from Controller and caches them      Should be called once after deployment, or when new system contracts are added      ⚠️ ASSUMPTION: Controller has ≤15 SmartContract entities (typical: 8-12)"}, "distributeToClaim(uint256)": {"params": {"totalAmount": "Total stablecoin to allocate (in STABLECOIN decimals, e.g., 1000000 = $1 USDC with 6 decimals)       🎯 CLAIM MODEL: This function does NOT transfer - it only updates accumulatedPerToken      Holders must call claim() to collect. This prevents malicious contracts from blocking distributions.      Smart contracts CAN participate - they handle their own receive() logic.            🚀 O(1) GAS COST: Only updates ONE global variable regardless of holder count!            Distribution formula:        perTokenIncrease = (totalAmount * PRECISION) / totalSupply        accumulatedPerToken += perTokenIncrease        holderClaimable = (balance * accumulatedPerToken - rewardDebt) / PRECISION            🔒 LOCKED FUNDS: totalOwedAmounts is increased and protected from admin withdrawal            🛡️ SAFETY: Always validates available balance (contractBalance - totalOwedAmounts)      This ensures solvency even if called multiple times (not idempotent by design)            💡 GAS OPTIMIZATION: Calculates balance once and delegates to internal _distributeToClaim      This avoids redundant external calls when used by onTokenTransferUpdate      "}, "details": "Does NOT transfer - holders must call claim() to collect", "returns": {"totalAllocated": "The total amount allocated"}}, "getClaimableAmount(address)": {"params": {"holder": "Address to check"}, "returns": {"amount": "Claimable amount in stablecoin decimals"}}, "peerTokenAvailable(address)": {"returns": {"_0": "The signed balance (can be negative if more was withdrawn than received) obviously the first lateral movement will be a withdrawal from a peerTreasury source"}}, "previewDistribution(uint256)": {"params": {"totalAmount": "Total amount to allocate"}, "details": "In O(1) claim model, distribution just updates one global variable      Each holder''s claimable increases by: balance * perTokenIncrease / PRECISION", "returns": {"perTokenIncrease": "How much the accumulatedPerToken would increase"}}, "setStableCoinAddress(address)": {"params": {"newStableCoinAddress": "New stablecoin contract address (e.g., USDC)"}, "details": "Can only be called by PlatformTreasurer      Updates stableCoinAddress for this contract and all children can access it      Made public virtual so IssueToken can override with super.setStableCoinAddress()"}, "setProjectRevenueTreasury(address)": {"params": {"_projectRevenueTreasury": "Address of ProjectRevenueTreasury (or address(0) to disable)"}, "details": "Can only be set by SmartContract entities (PRT calls this in its constructor)      Once set, onTokenTransferUpdate will notify PRT after each transfer  ⚠️ NOT \"SET ONCE\": This is intentionally updateable for operational flexibility    - Only platform authority can add SmartContracts (via Controller registration)    - If project has not permanently locked platform access, platform may update contracts    - An update to PRT would be easier if it could repoint PRT without replacing DistributionManager    - This is an \"open yet secure\" model: writable only by authorized SmartContracts  // TODO future, make IssueToken call feemanager.distribute directly and remove this method     Because feeMaanger notifies treasury already. On the other hand we only ned that notify    for transfers and this DM  is ALREADY registered so IssueToken calls back here to onTokenTransfer"}, "setAutoDistributeThreshold(uint256)": {"params": {"minPayoutThreshold": "Minimum balance to trigger auto-distribute        - Set to 0 to DISABLE auto-distribute (manual distributeToClaim only)        - Set to >= 10 to ENABLE auto-distribute (triggers on transfers when threshold met)"}, "details": "Only TreasuryAdmin can change this      Reverts if set to 1-9 (prevents excessive gas costs from frequent auto-distributes)      Example: 1000000000 = $1000 USDC (6 decimals) - reasonable for most projects"}, "setDistributionSupplyBasis(uint256)": {"params": {"newDistributionSupplyBasis": "Expected total circulating supply for fair distribution calculations        - Set to 0 to DISABLE (uses actual eligible supply only, normal behavior)        - Set to > 0 to ENABLE (prevents early buyer windfall during primary sales)"}, "details": "Only TreasuryAdmin or SCAdmin can change this      When enabled, distributions use MAX(actualEligibleSupply, distributionSupplyBasis) as denominator      Deferred amounts (difference between expected vs actual allocation) transfer to IssueToken treasury      Example: Set to 1000000e18 for expected 1M token final supply during ongoing token sales"}, "distributePercentageToClaim(uint256)": {"params": {"percentageBps": "Percentage in basis points (e.g., 5000 = 50%)"}, "details": "Gas-optimized: Calculates available balance once and uses internal _distributeToClaim", "returns": {"totalAllocated": "Actual amount allocated"}}, "peerTreasuryNotifyReceived(address,uint256)": {"params": {"token": "Token contract address  ", "amount": "Amount received"}}, "peerTreasuryTransferTokens(address,address,uint256)": {"details": "Follows ProjectRevenueTreasury pattern: protects totalOwedAmounts"}, "executiveWithdrawTokens(address,uint256,address,string)": {"details": "Cannot withdraw stablecoin if it would reduce balance below totalOwedAmounts      Only TreasuryAdmin or SCAdmin can withdraw  (see super version for more details)"}, "peerTreasuryTransferTokensDirect(address,address,uint256)": {"details": "Follows ProjectRevenueTreasury pattern: protects totalOwedAmounts"}, "onTokenTransferUpdate(address,address,uint256,uint256,uint256)": {"params": {"to": "Recipient address (address(0) for burns)", "from": "Sender address (address(0) for mints)", "value": "Amount transferred", "toBalanceBefore": "Recipient''s balance before transfer (passed from token for gas efficiency)", "fromBalanceBefore": "Sender''s balance before transfer (passed from token for gas efficiency)"}, "details": "Only callable by the bound IssueToken contract      Before balances passed from token = single source of truth (no shadow state drift)      Tracks when holders go from 0 → non-zero (activate) or non-zero → 0 (deactivate)      🔑 CRITICAL: Harvests rewards using BEFORE balances to lock in amounts  key: ontransferupdate  onupdatetransfer "}}, "version": 1, "stateVariables": {"rewardDebt": {"details": "rewardDebt = balance * accumulatedPerToken at last balance change      This ensures transfers don''t retroactively change claimable amounts      Formula: owed = (balance * accumulatedPerToken) - rewardDebt"}, "totalOwedAmounts": {"details": "This is LOCKED and cannot be withdrawn by TreasuryAdmin      Increases on distributeToClaim(), decreases on claim()"}, "activeHolderCount": {"details": "Decremented when balance goes to zero, incremented when balance becomes non-zero"}, "accumulatedPerToken": {"details": "This is the KEY to O(1) distribution gas cost      Each distributeToClaim() adds: (distributionAmount * PRECISION) / totalSupply      Holder''s owed = (balance * accumulatedPerToken - rewardDebt[holder]) / PRECISION"}, "claimableStoredScaled": {"details": "We store in scaled units to avoid rounding dust getting stuck forever.      claimableStoredScaled accumulates fractional parts until they become claimable.      IMPORTANT: balance going to 0 does NOT forfeit stored claimable."}, "excludedSmartContracts": {"details": "⚠️ CRITICAL ASSUMPTION: Controller will NEVER have more than ~15 SmartContract entities      This cache is populated on first distributeToClaim() OR via manual syncExcludedContracts() call      Avoids expensive Controller.getAllOfficialEntities() call on every distribution"}, "autoDistributeThreshold": {"details": "If getAvailableBalance() >= this amount, onTokenTransferUpdate() auto-distributes      Set to 0 to disable auto-distribute (default)      Set high (e.g., 1000000000 = $1000 USDC) to only auto-distribute on large accumulations      Available balance calculated as: balanceOf(this) - totalOwedAmounts"}, "distributionSupplyBasis": {"details": "When > 0, distributions use this as denominator instead of actual eligible supply      This prevents early buyers from getting windfall distributions during primary sales      Example: Set to 1,000,000 for expected final supply, distributions divide by this amount      Any deferred distribution (difference between expected vs actual) transfers to IssueToken treasury      When = 0, ignored (uses actual eligible supply, normal behavior)      Can be updated at any time by TreasuryAdmin to adjust for changing expectations"}}}, "sources": {"interfaces/IController.sol": {"id": 8}, "interfaces/IFeeManager.sol": {"id": 9}, "interfaces/IIssueToken.sol": {"id": 10}, "contracts/TreasuryConstants.sol": {"id": 7}, "contracts/ExecutivePeerTreasury.sol": {"id": 5}, "@openzeppelin/contracts/utils/Address.sol": {"id": 3}, "contracts/IssueTokenDistributionManager.sol": {"id": 6}, "@openzeppelin/contracts/token/ERC20/IERC20.sol": {"id": 0}, "@openzeppelin/contracts/utils/ReentrancyGuard.sol": {"id": 4}, "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol": {"id": 2}, "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol": {"id": 1}}, "userdoc": {"kind": "user", "errors": {"NotTokenAdmin()": [{"notice": "Shared errors to avoid duplicate declarations across treasury contracts"}]}, "notice": "Tracks token holders and allocates revenue/dividends PROPORTIONALLY using claim model", "methods": {"claim()": {"notice": "Claim accumulated distributions"}, "PRECISION()": {"notice": "Precision multiplier for per-token calculations (prevents rounding errors)"}, "issueToken()": {"notice": "The IssueToken that reports transfers to this manager"}, "receiveFee()": {"notice": "Receive ETH fees from FeeManager (ultra-lightweight, no accounting)"}, "KECCAK_SUPER()": {"notice": "Pre-computed keccak256 hash of \"Super\" for gas-optimized entity checks"}, "KECCAK_REGISTRAR()": {"notice": "Pre-computed keccak256 hash of \"Registrar\" for gas-optimized entity checks (platform/project registrars)"}, "peerETHAvailable()": {"notice": "Check ETH available (total received - total withdrawn)"}, "totalOwedAmounts()": {"notice": "Total amount owed to all holders (not yet claimed)"}, "activeHolderCount()": {"notice": "Count of holders with non-zero balance"}, "getEligibleSupply()": {"notice": "Get the current eligible supply (excludes smart contract entities)"}, "getPeerTreasuries()": {"notice": "Return all known peer treasury token entries"}, "rewardDebt(address)": {"notice": "Reward debt per holder - tracks already-accounted-for rewards"}, "KECCAK_TOKEN_ADMIN()": {"notice": "Pre-computed keccak256 hash of \"TokenAdmin\" for gas-optimized entity checks"}, "getPeerTreasuryETH()": {"notice": "Return ETH treasury data"}, "accumulatedPerToken()": {"notice": "Accumulated distribution per token (scaled by PRECISION)"}, "getAvailableBalance()": {"notice": "Get contract''s stablecoin balance available for distribution"}, "getActiveHolderCount()": {"notice": "Get active holder count (only holders with non-zero balance)"}, "KECCAK_LIQUIDITY_POOL()": {"notice": "Pre-computed keccak256 hash of \"LiquidityPool\" for gas-optimized entity checks"}, "KECCAK_SMART_CONTRACT()": {"notice": "Pre-computed keccak256 hash of \"SmartContract\" for gas-optimized entity checks"}, "KECCAK_TREASURY_ADMIN()": {"notice": "Pre-computed keccak256 hash of \"TreasuryAdmin\" for gas-optimized entity checks"}, "syncExcludedContracts()": {"notice": "Sync excluded SmartContract addresses from Controller (callable by TokenAdmin)"}, "KECCAK_SWAPPABLE_TOKEN()": {"notice": "Pre-computed keccak256 hash of \"SwappableToken\" for gas-optimized entity checks"}, "getPeerTreasury(address)": {"notice": "Return individual peer treasury entry for a token"}, "peerTreasuryReceiveETH()": {"notice": "Receive ETH from any source and track it"}, "projectRevenueTreasury()": {"notice": "ProjectRevenueTreasury to notify on token transfers (set once by PRT constructor)"}, "autoDistributeThreshold()": {"notice": "Minimum balance threshold to trigger auto-distribute on transfers"}, "distributionSupplyBasis()": {"notice": "Distribution supply basis for ongoing primary offerings"}, "distributeToClaim(uint256)": {"notice": "Allocate stablecoin PROPORTIONALLY to all active holders'' claimable amounts (EXTERNAL entry point)"}, "KECCAK_CONTROLLER_FACTORY()": {"notice": "Pre-computed keccak256 hash of \"ControllerFactory\" for entity type registration"}, "KECCAK_PLATFORM_TREASURER()": {"notice": "⚠️ DEPRECATED: PLATFORM_TREASURER check - use controller.isPlatformTreasuryAdmin() instead"}, "getClaimableAmount(address)": {"notice": "Check claimable amount for any address"}, "peerTokenAvailable(address)": {"notice": "Check token available (total received - total withdrawn)"}, "KECCAK_OFFICIAL_STABLECOIN()": {"notice": "Pre-computed keccak256 hash of \"OfficialStablecoin\" for stablecoin validation"}, "KECCAK_PLATFORM_CONTROLLER()": {"notice": "Pre-computed keccak256 hash of \"PLATFORM_CONTROLLER\" for entity type registration"}, "previewDistribution(uint256)": {"notice": "Preview distribution details for a given total amount"}, "setStableCoinAddress(address)": {"notice": "Set or update the stablecoin address used for fee payments"}, "KECCAK_THIRD_PARTY_REGISTRAR()": {"notice": "Pre-computed keccak256 hash of \"ThirdPartyRegistrar\" for gas-optimized entity checks (third-party KYC providers)"}, "claimableStoredScaled(address)": {"notice": "Stored claimable amount per holder (SCALED by PRECISION)"}, "KECCAK_REGISTERED_SAFE_FACTORY()": {"notice": "Pre-computed keccak256 hash of \"RegisteredSafeFactory\" for multi-sig safe registration"}, "setProjectRevenueTreasury(address)": {"notice": "Set ProjectRevenueTreasury for transfer fee notifications (same pattern as IssueToken.setDistributionManager)"}, "setAutoDistributeThreshold(uint256)": {"notice": "Enable/disable auto-distribute by setting minimum payout threshold"}, "setDistributionSupplyBasis(uint256)": {"notice": "Update distribution supply basis for ongoing primary offerings"}, "KECCAK_PLATFORM_FEE_CHAINED_ENTITY()": {"notice": "⚠️ DEPRECATED: FEE_CHAIN_TYPE is now encapsulated in FeeManager as DEFAULT_FEE_CHAIN_TYPE"}, "distributePercentageToClaim(uint256)": {"notice": "Allocate specific percentage of contract''s available stablecoin balance to claimable amounts"}, "peerTreasuryTransferETH(address,uint256)": {"notice": "Transfer ETH to another peer contract (OfficialEntity SmartContract)"}, "peerTreasuryReceiveTokens(address,uint256)": {"notice": "Receive ERC20 tokens and track source"}, "peerTreasuryNotifyReceived(address,uint256)": {"notice": "NOTIFICATION METHOD - Update counters when tokens received via direct transfer"}, "peerTreasuryTran