alType":"bytes32","name":"","type":"bytes32"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"KECCAK_TREASURY_ADMIN","outputs":[{"internalType":"bytes32","name":"","type":"bytes32"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"PRECISION","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"accumulatedPerToken","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"activeHolderCount","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"autoDistributeThreshold","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"claim","outputs":[{"internalType":"uint256","name":"amount","type":"uint256"}],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"address","name":"","type":"address"}],"name":"claimableStoredScaled","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"uint256","name":"percentageBps","type":"uint256"}],"name":"distributePercentageToClaim","outputs":[{"internalType":"uint256","name":"totalAllocated","type":"uint256"}],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint256","name":"totalAmount","type":"uint256"}],"name":"distributeToClaim","outputs":[{"internalType":"uint256","name":"totalAllocated","type":"uint256"}],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"distributionSupplyBasis","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"address","name":"personAddress","type":"address"},{"internalType":"uint256","name":"amt","type":"uint256"},{"internalType":"string","name":"note","type":"string"}],"name":"executiveWithdrawETH","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"address","name":"personAddress","type":"address"},{"internalType":"uint256","name":"amt","type":"uint256"},{"internalType":"address","name":"tokenSCAddress","type":"address"},{"internalType":"string","name":"note","type":"string"}],"name":"executiveWithdrawTokens","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"feeManager","outputs":[{"internalType":"address","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"getActiveHolderCount","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"getAllWithdrawals","outputs":[{"components":[{"internalType":"address","name":"to","type":"address"},{"internalType":"address","name":"asset","type":"address"},{"internalType":"uint256","name":"amt","type":"uint256"},{"internalType":"string","name":"note","type":"string"}],"internalType":"struct ExecutivePeerTreasury.Withdrawal[]","name":"","type":"tuple[]"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"getAvailableBalance","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"address","name":"holder","type":"address"}],"name":"getClaimableAmount","outputs":[{"internalType":"uint256","name":"amount","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"getEligibleSupply","outputs":[{"internalType":"uint256","name":"eligibleSupply","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"getPeerTreasuries","outputs":[{"components":[{"internalType":"address","name":"token","type":"address"},{"internalType":"uint256","name":"totalReceived","type":"uint256"},{"internalType":"uint256","name":"totalWithdrawn","type":"uint256"}],"internalType":"struct ExecutivePeerTreasury.TreasurySnapshot[]","name":"","type":"tuple[]"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"address","name":"token","type":"address"}],"name":"getPeerTreasury","outputs":[{"internalType":"uint256","name":"received","type":"uint256"},{"internalType":"uint256","name":"withdrawn","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"getPeerTreasuryETH","outputs":[{"internalType":"uint256","name":"received","type":"uint256"},{"internalType":"uint256","name":"withdrawn","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"issueToken","outputs":[{"internalType":"address","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"issueTokenAddress","outputs":[{"internalType":"address","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"address","name":"from","type":"address"},{"internalType":"address","name":"to","type":"address"},{"internalType":"uint256","name":"value","type":"uint256"},{"internalType":"uint256","name":"fromBalanceBefore","type":"uint256"},{"internalType":"uint256","name":"toBalanceBefore","type":"uint256"}],"name":"onTokenTransferUpdate","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"peerETHAvailable","outputs":[{"internalType":"int256","name":"","type":"int256"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"address","name":"token","type":"address"}],"name":"peerTokenAvailable","outputs":[{"internalType":"int256","name":"","type":"int256"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"peerTreasuryController","outputs":[{"internalType":"address","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"address","name":"token","type":"address"},{"internalType":"uint256","name":"amount","type":"uint256"}],"name":"peerTreasuryNotifyReceived","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"peerTreasuryReceiveETH","outputs":[],"stateMutability":"payable","type":"function"},{"inputs":[{"internalType":"address","name":"token","type":"address"},{"internalType":"uint256","name":"amount","type":"uint256"}],"name":"peerTreasuryReceiveTokens","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"address payable","name":"to","type":"address"},{"internalType":"uint256","name":"amount","type":"uint256"}],"name":"peerTreasuryTransferETH","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"address","name":"token","type":"address"},{"internalType":"address","name":"to","type":"address"},{"internalType":"uint256","name":"amount","type":"uint256"}],"name":"peerTreasuryTransferTokens","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"address","name":"token","type":"address"},{"internalType":"address","name":"to","type":"address"},{"internalType":"uint256","name":"amount","type":"uint256"}],"name":"peerTreasuryTransferTokensDirect","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint256","name":"totalAmount","type":"uint256"}],"name":"previewDistribution","outputs":[{"internalType":"uint256","name":"perTokenIncrease","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"projectRevenueTreasury","outputs":[{"internalType":"address","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"receiveFee","outputs":[],"stateMutability":"payable","type":"function"},{"inputs":[{"internalType":"address","name":"","type":"address"}],"name":"rewardDebt","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"},{"inputs":[{"internalType":"uint256","name":"minPayoutThreshold","type":"uint256"}],"name":"setAutoDistributeThreshold","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint256","name":"newDistributionSupplyBasis","type":"uint256"}],"name":"setDistributionSupplyBasis","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"address","name":"_projectRevenueTreasury","type":"address"}],"name":"setProjectRevenueTreasury","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"address","name":"newStableCoinAddress","type":"address"}],"name":"setStableCoinAddress","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"stableCoinAddress","outputs":[{"internalType":"address","name":"","type":"address"}],"stateMutability":"view","type":"function"},{"inputs":[],"name":"syncExcludedContracts","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[],"name":"totalOwedAmounts","outputs":[{"internalType":"uint256","name":"","type":"uint256"}],"stateMutability":"view","type":"function"}],"devdoc":{"details":"Called by IssueToken on every transfer to maintain holder registry      Distribution allocation requires TreasuryAdmin permission      Holders call claim() to collect their distributions (pay their own gas)  🎯 CLAIM-BASED MODEL: - TreasuryAdmin calls distributeToClaim() to allocate funds (O(1) gas!) - Holders call claim() to collect their proportional share (pays own gas) - Smart contracts CAN participate and handle their own receive() logic - No risk of malicious contracts blocking distributions  🚀 O(1) SCALABILITY: - Uses accumulatedPerToken global variable (scales to millions of holders) - rewardDebt pattern ensures transfers don''t retroactively change claims - Harvest-on-transfer locks in rewards at old balance before balance changes  Key Features: - PROPORTIONAL allocation: each holder receives (balance / totalSupply) * totalAmount - Tracks all-time holders array (never shrinks - gas optimization) - Maintains active holder count (decrements when balance → 0) - Uses token.balanceOf() as single source of truth (passed from token on transfers) - Protects owed distributions: totalOwedAmounts locked from admin withdrawal - Extends ExecutivePeerTreasury for admin controls + ReentrancyGuard","errors":{"AddressEmptyCode(address)":[{"details":"There''s no code at `target` (it is not a contract)."}],"AddressInsufficientBalance(address)":[{"details":"The ETH balance of the account is not enough to perform the operation."}],"FailedInnerCall()":[{"details":"A call to an address target failed. The target may have reverted."}],"ReentrancyGuardReentrantCall()":[{"details":"Unauthorized reentrant call."}],"SafeERC20FailedDecreaseAllowance(address,uint256,uint256)":[{"details":"Indicates a failed `decreaseAllowance` request."}],"SafeERC20FailedOperation(address)":[{"details":"An operation with an ERC20 token failed."}]},"kind":"dev","methods":{"claim()":{"details":"Anyone can call to claim their own distributions      Uses rewardDebt pattern: owed = (balance * accumulatedPerToken) - rewardDebt      EOAs pay their own gas - they decide when it''s worth claiming      Smart contracts CAN claim too - they handle their own receive() logic","returns":{"amount":"Amount claimed"}},"constructor":{"params":{"_controller":"Controller address for permission checks","_distributionSupplyBasis":"Expected total supply for distribution calculations (0 = disabled, uses actual supply)","_initialAutoDistributeThreshold":"Initial auto-distribute threshold (0 = disabled, >= 100 to enable)","_issueTokenAddress":"IssueToken address (only this token can report transfers)"}},"distributePercentageToClaim(uint256)":{"details":"Gas-optimized: Calculates available balance once and uses internal _distributeToClaim","params":{"percentageBps":"Percentage in basis points (e.g., 5000 = 50%)"},"returns":{"totalAllocated":"Actual amount allocated"}},"distributeToClaim(uint256)":{"details":"Does NOT transfer - holders must call claim() to collect","params":{"totalAmount":"Total stablecoin to allocate (in STABLECOIN decimals, e.g., 1000000 = $1 USDC with 6 decimals)       🎯 CLAIM MODEL: This function does NOT transfer - it only updates accumulatedPerToken      Holders must call claim() to collect. This prevents malicious contracts from blocking distributions.      Smart contracts CAN participate - they handle their own receive() logic.            🚀 O(1) GAS COST: Only updates ONE global variable regardless of holder count!            Distribution formula:        perTokenIncrease = (totalAmount * PRECISION) / totalSupply        accumulatedPerToken += perTokenIncrease        holderClaimable = (balance * accumulatedPerToken - rewardDebt) / PRECISION            🔒 LOCKED FUNDS: totalOwedAmounts is increased and protected from admin withdrawal            🛡️ SAFETY: Always validates available balance (contractBalance - totalOwedAmounts)      This ensures solvency even if called multiple times (not idempotent by design)            💡 GAS OPTIMIZATION: Calculates balance once and delegates to internal _distributeToClaim      This avoids redundant external calls when used by onTokenTransferUpdate      "},"returns":{"totalAllocated":"The total amount allocated"}},"executiveWithdrawTokens(address,uint256,address,string)":{"details":"Cannot withdraw stablecoin if it would reduce balance below totalOwedAmounts      Only TreasuryAdmin or SCAdmin can withdraw  (see super version for more details)"},"getActiveHolderCount()":{"details":"This is maintained automatically on every transfer      If deployed late, this will be 0 initially and build up as transfers occur"},"getAvailableBalance()":{"details":"Available = balanceOf(this) - totalOwedAmounts      This is what can be distributed or withdrawn by admin"},"getClaimableAmount(address)":{"params":{"holder":"Address to check"},"returns":{"amount":"Claimable amount in stablecoin decimals"}},"getEligibleSupply()":{"returns":{"eligibleSupply":"The circulating supply available for distributions"}},"onTokenTransferUpdate(address,address,uint256,uint256,uint256)":{"details":"Only callable by the bound IssueToken contract      Before balances passed from token = single source of truth (no shadow state drift)      Tracks when holders go from 0 → non-zero (activate) or non-zero → 0 (deactivate)      🔑 CRITICAL: Harvests rewards using BEFORE balances to lock in amounts  key: ontransferupdate  onupdatetransfer ","params":{"from":"Sender address (address(0) for mints)","fromBalanceBefore":"Sender''s balance before transfer (passed from token for gas efficiency)","to":"Recipient address (address(0) for burns)","toBalanceBefore":"Recipient''s balance before transfer (passed from token for gas efficiency)","value":"Amount transferred"}},"peerETHAvailable()":{"returns":{"_0":"The signed balance (can be negative if more was withdrawn than received - which is OK!) obviously the first lateral movement will be a withdrawal from a peerTreasury source"}},"peerTokenAvailable(address)":{"returns":{"_0":"The signed balance (can be negative if more was withdrawn than received) obviously the first lateral movement will be a withdrawal from a peerTreasury source"}},"peerTreasuryNotifyReceived(address,uint256)":{"params":{"amount":"Amount received","token":"Token contract address  "}},"peerTreasuryTransferTokens(address,address,uint256)":{"details":"Follows ProjectRevenueTreasury pattern: protects totalOwedAmounts"},"peerTreasuryTransferTokensDirect(address,address,uint256)":{"details":"Follows ProjectRevenueTreasury pattern: protects totalOwedAmounts"},"previewDistribution(uint256)":{"details":"In O(1) claim model, distribution just updates one global variable      Each holder''s claimable increases by: balance * perTokenIncrease / PRECISION","params":{"totalAmount":"Total amount to allocate"},"returns":{"perTokenIncrease":"How much the accumulatedPerToken would increase"}},"receiveFee()":{"details":"ONLY for FeeManager → ProjectRevenueTreasury ETH fee distribution      Does NOT update totalReceived (reserved for peer-to-peer transfer accounting)      Does NOT emit events (gas optimization)      ⚠️ Use peerTreasuryReceiveETH() for tracked peer transfers that trigger downstream logic      ⚠️ NORMAL OPERATION: Funds received via this method are NOT auto-deployed         They accumulate in treasury balance until processRevenueAndDisperse() is called"},"setAutoDistributeThreshold(uint256)":{"details":"Only TreasuryAdmin can change this      Reverts if set to 1-9 (prevents excessive gas costs from frequent auto-distributes)      Example: 1000000000 = $1000 USDC (6 decimals) - reasonable for most projects","params":{"minPayoutThreshold":"Minimum balance to trigger auto-distribute        - Set to 0 to DISABLE auto-distribute (manual distributeToClaim only)        - Set to >= 10 to ENABLE auto-distribute (triggers on transfers when threshold met)"}},"setDistributionSupplyBasis(uint256)":{"details":"Only TreasuryAdmin or SCAdmin can change this      When enabled, distributions use MAX(actualEligibleSupply, distributionSupplyBasis) as denominator      Deferred amounts (difference between expected vs actual allocation) transfer to IssueToken treasury      Example: Set to 1000000e18 for expected 1M token final supply during ongoing token sales","params":{"newDistributionSupplyBasis":"Expected total circulating supply for fair distribution calculations        - Set to 0 to DISABLE (uses actual eligible supply only, normal behavior)        - Set to > 0 to ENABLE (prevents early buyer windfall during primary sales)"}},"setProjectRevenueTreasury(address)":{"details":"Can only be set by SmartContract entities (PRT calls this in its constructor)      Once set, onTokenTransferUpdate will notify PRT after each transfer  ⚠️ NOT \"SET ONCE\": This is intentionally updateable for operational flexibility    - Only platform authority can add SmartContracts (via Controller registration)    - If project has not permanently locked platform access, platform may update contracts    - An update to PRT would be easier if it could repoint PRT without replacing DistributionManager    - This is an \"open yet secure\" model: writable only by authorized SmartContracts  // TODO future, make IssueToken call feemanager.distribute directly and remove this method     Because feeMaanger notifies treasury already. On the other hand we only ned that notify    for transfers and this DM  is ALREADY registered so IssueToken calls back here to onTokenTransfer","params":{"_projectRevenueTreasury":"Address of ProjectRevenueTreasury (or address(0) to disable)"}},"setStableCoinAddress(address)":{"details":"Can only be called by PlatformTreasurer      Updates stableCoinAddress for this contract and all children can access it      Made public virtual so IssueToken can override with super.setStableCoinAddress()","params":{"newStableCoinAddress":"New stablecoin contract address (e.g., USDC)"}},"syncExcludedContracts()":{"details":"Fetches all SmartContract entities from Controller and caches them      Should be called once after deployment, or when new system contracts are added      ⚠️ ASSUMPTION: Controller has ≤15 SmartContract entities (typical: 8-12)"}},"stateVariables":{"accumulatedPerToken":{"details":"This is the KEY to O(1) distribution gas cost      Each distributeToClaim() adds: (distributionAmount * PRECISION) / totalSupply      Holder''s owed = (balance * accumulatedPerToken - rewardDebt[holder]) / PRECISION"},"activeHolderCount":{"details":"Decremented when balance goes to zero, incremented when balance becomes non-zero"},"autoDistributeThreshold":{"details":"If getAvailableBalance() >= this amount, onTokenTransferUpdate() auto-distributes      Set to 0 to disable auto-distribute (default)      Set high (e.g., 1000000000 = $1000 USDC) to only auto-distribute on large accumulations      Available balance calculated as: balanceOf(this) - totalOwedAmounts"},"claimableStoredScaled":{"details":"We store in scaled units to avoid rounding dust getting stuck forever.      claimableStoredScaled accumulates fractional parts until they become claimable.      IMPORTANT: balance going to 0 does NOT forfeit stored claimable."},"distributionSupplyBasis":{"details":"When > 0, distributions use this as denominator instead of actual eligible supply      This prevents early buyers from getting windfall distributions during primary sales      Example: Set to 1,000,000 for expected final supply, distributions divide by this amount      Any deferred distribution (difference between expected vs actual) transfers to IssueToken treasury      When = 0, ignored (uses actual eligible supply, normal behavior)      Can be updated at any time by TreasuryAdmin to adjust for changing expectations"},"excludedSmartContracts":{"details":"⚠️ CRITICAL ASSUMPTION: Controller will NEVER have more than ~15 SmartContract entities      This cache is populated on first distributeToClaim() OR via manual syncExcludedContracts() call      Avoids expensive Controller.getAllOfficialEntities() call on every distribution"},"rewardDebt":{"details":"rewardDebt = balance * accumulatedPerToken at last balance change      This ensures transfers don''t retroactively change claimable amounts      Formula: owed = (balance * accumulatedPerToken) - rewardDebt"},"totalOwedAmounts":{"details":"This is LOCKED and cannot be withdrawn by TreasuryAdmin      Increases on distributeToClaim(), decreases on claim()"}},"title":"IssueTokenDistributionManager","version":1},"userdoc":{"errors":{"NotTokenAdmin()":[{"notice":"Shared errors to avoid duplicate declarations across treasury contracts"}]},"kind":"user","methods":{"KECCAK_CONTROLLER_FACTORY()":{"notice":"Pre-computed keccak256 hash of \"ControllerFactory\" for entity type registration"},"KECCAK_LIQUIDITY_POOL()":{"notice":"Pre-computed keccak256 hash of \"LiquidityPool\" for gas-optimized entity checks"},"KECCAK_OFFICIAL_STABLECOIN()":{"notice":"Pre-computed keccak256 hash of \"OfficialStablecoin\" for stablecoin validation"},"KECCAK_PLATFORM_CONTROLLER()":{"notice":"Pre-computed keccak256 hash of \"PLATFORM_CONTROLLER\" for entity type registration"},"KECCAK_PLATFORM_FEE_CHAINED_ENTITY()":{"notice":"⚠️ DEPRECATED: FEE_CHAIN_TYPE is now encapsulated in FeeManager as DEFAULT_FEE_CHAIN_TYPE"},"KECCAK_PLATFORM_TREASURER()":{"notice":"⚠️ DEPRECATED: PLATFORM_TREASURER check - use controller.isPlatformTreasuryAdmin() instead"},"KECCAK_REGISTERED_SAFE_FACTORY()":{"notice":"Pre-computed keccak256 hash of \"RegisteredSafeFactory\" for multi-sig safe registration"},"KECCAK_REGISTRAR()":{"notice":"Pre-computed keccak256 hash of \"Registrar\" for gas-optimized entity checks (platform/project registrars)"},"KECCAK_SMART_CONTRACT()":{"notice":"Pre-computed keccak256 hash of \"SmartContract\" for gas-optimized entity checks"},"KECCAK_SUPER()":{"notice":"Pre-computed keccak256 hash of \"Super\" for gas-optimized entity checks"},"KECCAK_SWAPPABLE_TOKEN()":{"notice":"Pre-computed keccak256 hash of \"SwappableToken\" for gas-optimized entity checks"},"KECCAK_THIRD_PARTY_REGISTRAR()":{"notice":"Pre-computed keccak256 hash of \"ThirdPartyRegistrar\" for gas-optimized entity checks (third-party KYC providers)"},"KECCAK_TOKEN_ADMIN()":{"notice":"Pre-computed keccak256 hash of \"TokenAdmin\" for gas-optimized entity checks"},"KECCAK_TREASURY_ADMIN()":{"notice":"Pre-computed keccak256 hash of \"TreasuryAdmin\" for gas-optimized entity checks"},"PRECISION()":{"notice":"Precision multiplier for per-token calculations (prevents rounding errors)"},"accumulatedPerToken()":{"notice":"Accumulated distribution per token (scaled by PRECISION)"},"activeHolderCount()":{"notice":"Count of holders with non-zero balance"},"autoDistributeThreshold()":{"notice":"Minimum balance threshold to trigger auto-distribute on transfers"},"claim()":{"notice":"Claim accumulated distributions"},"claimableStoredScaled(address)":{"notice":"Stored claimable amount per holder (SCALED by PRECISION)"},"distributePercentageToClaim(uint256)":{"notice":"Allocate specific percentage of contract''s available stablecoin balance to claimable amounts"},"distributeToClaim(uint256)":{"notice":"Allocate stablecoin PROPORTIONALLY to all active holders'' claimable amounts (EXTERNAL entry point)"},"distributionSupplyBasis()":{"notice":"Distribution supply basis for ongoing primary offerings"},"executiveWithdrawTokens(address,uint256,address,string)":{"notice":"Override ExecutivePeerTreasury withdrawal to protect owed distributions"},"getActiveHolderCount()":{"notice":"Get active holder count (only holders with non-zero balance)"},"getAvailableBalance()":{"notice":"Get contract''s stablecoin balance available for distribution"},"getClaimableAmount(address)":{"notice":"Check claimable amount for any address"},"getEligibleSupply()":{"notice":"Get the current eligible supply (excludes smart contract entities)"},"getPeerTreasuries()":{"notice":"Return all known peer treasury token entries"},"getPeerTreasury(address)":{"notice":"Return individual peer treasury entry for a token"},"getPeerTreasuryETH()":{"notice":"Return ETH treasury data"},"issueToken()":{"notice":"The IssueToken that reports transfers to this manager"},"onTokenTransferUpdate(address,address,uint256,uint256,uint256)":{"notice":"Called by IssueToken on every transfer to track holder status"},"peerETHAvailable()":{"notice":"Check ETH available (total received - total withdrawn)"},"peerTokenAvailable(address)":{"notice":"Check token available (total received - total withdrawn)"},"peerTreasuryNotifyReceived(address,uint256)":{"notice":"NOTIFICATION METHOD - Update counters when tokens received via direct transfer"},"peerTreasuryReceiveETH()":{"notice":"Receive ETH from any source and track it"},"peerTreasuryReceiveTokens(address,uint256)":{"notice":"Receive ERC20 tokens and track source"},"peerTreasuryTransferETH(address,uint256)":{"notice":"Transfer ETH to another peer contract (OfficialEntity SmartContract)"},"peerTreasuryTransferTokens(address,address,uint256)":{"notice":"Override to prevent withdrawal of owed distributions"},"peerTreasuryTransferTokensDirect(address,address,uint256)":{"notice":"Override to prevent withdrawal of owed distributions"},"previewDistribution(uint256)":{"notice":"Preview distribution details for a given total amount"},"projectRevenueTreasury()":{"notice":"ProjectRevenueTreasury to notify on token transfers (set once by PRT constructor)"},"receiveFee()":{"notice":"Receive ETH fees from FeeManager (ultra-lightweight, no accounting)"},"rewardDebt(address)":{"notice":"Reward debt per holder - tracks already-accounted-for rewards"},"setAutoDistributeThreshold(uint256)":{"notice":"Enable/disable auto-distribute by setting minimum payout threshold"},"setDistributionSupplyBasis(uint256)":{"notice":"Update distribution supply basis for ongoing primary offerings"},"setProjectRevenueTreasury(address)":{"notice":"Set ProjectRevenueTreasury for transfer fee notifications (same pattern as IssueToken.setDistributionManager)"},"setStableCoinAddress(address)":{"notice":"Set or update the stablecoin address used for fee payments"},"syncExcludedContracts()":{"notice":"Sync excluded SmartContract addresses from Controller (callable by TokenAdmin)"},"totalOwedAmounts()":{"notice":"Total amount owed to all holders (not yet claimed)"}},"notice":"Tracks token holders and allocates revenue/dividends PROPORTIONALLY using claim model","version":1}},"settings":{"compilationTarget":{"contracts/IssueTokenDistributionManager.sol":"IssueTokenDistributionManager"},"evmVersion":"prague","libraries":{},"metadata":{"bytecodeHash":"ipfs","useLiteralContent":true},"optimizer":{"enabled":true,"runs":10000},"remappings":[],"viaIR":true},"sources":{"@openzeppelin/contracts/token/ERC20/IERC20.sol":{"content":"// SPDX-License-Identifier: MIT\n// OpenZeppelin Contracts (last updated v5.0.0) (token/ERC20/IERC20.sol)\n\npragma solidity ^0.8.20;\n\n/**\n * @dev Interface of the ERC20 standard as defined in the EIP.\n */\ninterface IERC20 {\n    /**\n     * @dev Emitted when `value` tokens are moved from one account (`from`) to\n     * another (`to`).\n     *\n     * Note that `value` may be zero.\n     */\n    event Transfer(address indexed from, address indexed to, uint256 value);\n\n    /**\n     * @dev Emitted when the allowance of a `spender` for an `owner` is set by\n     * a call to {approve}. `value` is the new allowance.\n     */\n    event Approval(address indexed owner, address indexed spender, uint256 value);\n\n    /**\n     * @dev Returns the value of tokens in existence.\n     */\n    function totalSupply() external view returns (uint256);\n\n    /**\n     * @dev Returns the value of tokens owned by `account`.\n     */\n    function balanceOf(address account) external view returns (uint256);\n\n    /**\n     * @dev Moves a `value` amount of tokens from the caller''s account to `to`.\n     *\n     * Returns a boolean value indicating whether the operation succeeded.\n     *\n     * Emits a {Transfer} event.\n     */\n    function transfer(address to, uint256 value) external returns (bool);\n\n    /**\n     * @dev Returns the remaining number of tokens that `spender` will be\n     * allowed to spend on behalf of `owner` through {transferFrom}. This is\n     * zero by default.\n     *\n     * This value changes when {approve} or {transferFrom} are called.\n     */\n    function allowance(address owner, address spender) external view returns (uint256);\n\n    /**\n     * @dev Sets a `value` amount of tokens as the allowance of `spender` over the\n     * caller''s tokens.\n     *\n     * Returns a boolean value indicating whether the operation succeeded.\n     *\n     * IMPORTANT: Beware that changing an allowance with this method brings the risk\n     * that someone may use both the old and the new allowance by unfortunate\n     * transaction ordering. One possible solution to mitigate this race\n     * condition is to first reduce the spender''s