INSERT INTO sources (source_hash, source_hash_keccak, content, created_at, updated_at, created_by, updated_by) VALUES ('\x0438e7cf2ee8080897435942857729609c0dcbe2ea681f89e759b42d35c38c9e', '\x937abcaf1ae60ac24e01229803f7fd44e5d7bbba9af301daff10da6277886705', '// SPDX-License-Identifier: MIT
pragma solidity ^0.8.9;

import "./TransitiveRiskyLibrary.sol";

contract SafeContractWithTransitiveLibraryCall {
    function safe() public view returns (bool) {
        return TransitiveRiskyLibrary.isContract(address(this));
    }
}
