// @author Ken Silverman
// @dev Tracks all-time token holders and distributes USDC/stablecoin to active holders
//      Integrated with IssueToken via onTokenTransferUpdate() callback
//      Distribution triggered manually by TreasuryAdmin with configurable min per holder

pragma solidity 0.8.30;

import "./ExecutivePeerTreasury.sol";
import "../interfaces/IController.sol";
import "../interfaces/IIssueToken.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/* ========== CUSTOM ERRORS ========== */

error OnlyTokenContract();
error OnlyTreasuryOrSCAdmin();
error Unauthorized();
// InvalidTokenAddress - inherited from ExecutivePeerTreasury
// InvalidController - inherited from ExecutivePeerTreasury
error AmountTooLow();
error ThresholdTooLow();
error NoActiveHolders();
error InsufficientBalance();
error TransferFailed();

/// @notice Interface for ProjectRevenueTreasury notification hook
interface IProjectRevenueTreasury {
    function onTransferFeeDistributed() external;
}

/**
 * @title IssueTokenDistributionManager
 * @notice Tracks token holders and allocates revenue/dividends PROPORTIONALLY using claim model
 * @dev Called by IssueToken on every transfer to maintain holder registry
 *      Distribution allocation requires TreasuryAdmin permission
 *      Holders call claim() to collect their distributions (pay their own gas)
 * 
 * 🎯 CLAIM-BASED MODEL:
 * - TreasuryAdmin calls distributeToClaim() to allocate funds (O(1) gas!)
 * - Holders call claim() to collect their proportional share (pays own gas)
 * - Smart contracts CAN participate and handle their own receive() logic
 * - No risk of malicious contracts blocking distributions
 * 
 * 🚀 O(1) SCALABILITY:
 * - Uses accumulatedPerToken global variable (scales to millions of holders)
 * - rewardDebt pattern ensures transfers don''t retroactively change claims
 * - Harvest-on-transfer locks in rewards at old balance before balance changes
 * 
 * Key Features:
 * - PROPORTIONAL allocation: each holder receives (balance / totalSupply) * totalAmount
 * - Tracks all-time holders array (never shrinks - gas optimization)
 * - Maintains active holder count (decrements when balance → 0)
 * - Uses token.balanceOf() as single source of truth (passed from token on transfers)
 * - Protects owed distributions: totalOwedAmounts locked from admin withdrawal
 * - Extends ExecutivePeerTreasury for admin controls + ReentrancyGuard
 */
contract IssueTokenDistributionManager is ExecutivePeerTreasury, ReentrancyGuard {
    using SafeERC20 for IERC20;

    /* ========== IMMUTABLES ========== */
    
    /// @notice The IssueToken that reports transfers to this manager
    address public immutable issueToken;
    
    /// @notice ProjectRevenueTreasury to notify on token transfers (set once by PRT constructor)
    address public projectRevenueTreasury;
    
    /// @notice Stablecoin (USDC) used for distributions (inherited from ExecutivePeerTreasury)
    /// @dev Access via parent''s stableCoinAddress variable (not immutable, can be updated via setter)

    /* ========== STATE VARIABLES ========== */
    
    /// @notice All-time holders (never removed, only grows)
    // REMOVED: allTimeHolders - now use IssueToken.getHolderList() as single source of truth
    // REMOVED: isRegisteredHolder - no longer needed
    
    /// @notice Tracked balance for each holder (maintained internally, no token callbacks)
    // REMOVED: trackedBalance mapping - now using token.balanceOf() as single source of truth
    
    /// @notice Count of holders with non-zero balance
    /// @dev Decremented when balance goes to zero, incremented when balance becomes non-zero
    uint256 public activeHolderCount;
    
    /// @notice Accumulated distribution per token (scaled by PRECISION)
    /// @dev This is the KEY to O(1) distribution gas cost
    ///      Each distributeToClaim() adds: (distributionAmount * PRECISION) / totalSupply
    ///      Holder''s owed = (balance * accumulatedPerToken - rewardDebt[holder]) / PRECISION
    uint256 public accumulatedPerToken;
    
    /// @notice Precision multiplier for per-token calculations (prevents rounding errors)
    uint256 public constant PRECISION = 1e18;
    
    /// @notice Reward debt per holder - tracks already-accounted-for rewards
    /// @dev rewardDebt = balance * accumulatedPerToken at last balance change
    ///      This ensures transfers don''t retroactively change claimable amounts
    ///      Formula: owed = (balance * accumulatedPerToken) - rewardDebt
    mapping(address => uint256) public rewardDebt;
    
    /// @notice Stored claimable amount per holder (SCALED by PRECISION)
    /// @dev We store in scaled units to avoid rounding dust getting stuck forever.
    ///      claimableStoredScaled accumulates fractional parts until they become claimable.
    ///      IMPORTANT: balance going to 0 does NOT forfeit stored claimable.
    mapping(address => uint256) public claimableStoredScaled;

    /// @notice Total amount owed to all holders (not yet claimed)
    /// @dev This is LOCKED and cannot be withdrawn by TreasuryAdmin
    ///      Increases on distributeToClaim(), decreases on claim()
    uint256 public totalOwedAmounts;
    
    /// @notice Minimum balance threshold to trigger auto-distribute on transfers
    /// @dev If getAvailableBalance() >= this amount, onTokenTransferUpdate() auto-distributes
    ///      Set to 0 to disable auto-distribute (default)
    ///      Set high (e.g., 1000000000 = $1000 USDC) to only auto-distribute on large accumulations
    ///      Available balance calculated as: balanceOf(this) - totalOwedAmounts
    uint256 public autoDistributeThreshold;
    
    /// @notice Cached SmartContract addresses for supply exclusion (populated once, manually synced)
    /// @dev ⚠️ CRITICAL ASSUMPTION: Controller will NEVER have more than ~15 SmartContract entities
    ///      This cache is populated on first distributeToClaim() OR via manual syncExcludedContracts() call
    ///      Avoids expensive Controller.getAllOfficialEntities() call on every distribution
    address[] private excludedSmartContracts;
    
    /// @notice Distribution supply basis for ongoing primary offerings
    /// @dev When > 0, distributions use this as denominator instead of actual eligible supply
    ///      This prevents early buyers from getting windfall distributions during primary sales
    ///      Example: Set to 1,000,000 for expected final supply, distributions divide by this amount
    ///      Any deferred distribution (difference between expected vs actual) transfers to IssueToken treasury
    ///      When = 0, ignored (uses actual eligible supply, normal behavior)
    ///      Can be updated at any time by TreasuryAdmin to adjust for changing expectations
    uint256 public distributionSupplyBasis;
    
    uint256 public constant CONTRACT_VERSION = 43103; // 4.x.x.x - initial release synced

    /* ========== EVENTS ========== */
    
    event DistributionAllocated(
        address indexed executor,
        uint256 totalAmount,
        uint256 perTokenIncrease,
        uint256 timestamp
    );
    event Claimed(
        address indexed holder,
        uint256 amount,
        uint256 timestamp
    );

    event AutoDistributeThresholdUpdated(uint256 newThreshold);
    event AutoDistributeTriggered(uint256 amount, uint256 timestamp);
    event DistributionSupplyBasisUpdated(uint256 newBasis);
    event DeferredDistributionToTokenTreasury(
        uint256 deferredAmount,
        uint256 actualEligibleSupply,
        uint256 distributionSupplyBasis,
        uint256 timestamp
    );

    /* ========== MODIFIERS ========== */
    
    /// @notice Only the bound IssueToken can call holder tracking functions
    modifier onlyToken() {
        if (msg.sender != issueToken) revert OnlyTokenContract();
        _;
    }

    /* ========== CONSTRUCTOR ========== */
    
    /**
     * @param _controller Controller address for permission checks
     * @param _issueTokenAddress IssueToken address (only this token can report transfers)
     * @param _initialAutoDistributeThreshold Initial auto-distribute threshold (0 = disabled, >= 100 to enable)
     * @param _distributionSupplyBasis Expected total supply for distribution calculations (0 = disabled, uses actual supply)
     */
    constructor(
        address _controller,
        address _feeManager,
        address _issueTokenAddress,
        uint256 _initialAutoDistributeThreshold,
        uint256 _distributionSupplyBasis
    ) ExecutivePeerTreasury(_controller, _feeManager, _issueTokenAddress, "IssueTokenDistributionManager") {
        if (_issueTokenAddress == address(0)) revert InvalidTokenAddress();
        if (_controller == address(0)) revert InvalidController();
        
        // Validate threshold: 0 (disabled) or >= 100 (enabled with reasonable minimum)
        if (_initialAutoDistributeThreshold > 0 && _initialAutoDistributeThreshold < 100) {
            revert ThresholdTooLow();
        }
        
        issueToken = _issueTokenAddress;
        
        // Get stablecoin address from the token and set parent''s stableCoinAddress
        // (Parent ExecutivePeerTreasury.stableCoinAddress is not set when _issueToken == address(this))
        address _stableCoin = IIssueToken(_issueTokenAddress).stableCoinAddress();
        if (_stableCoin == address(0)) revert InvalidTokenAddress();
        stableCoinAddress = _stableCoin; // Set parent''s variable
        
        autoDistributeThreshold = _initialAutoDistributeThreshold; // Set at deployment (can change via setter later)
        distributionSupplyBasis = _distributionSupplyBasis; // Set at deployment (0 = disabled, can change via setter later)
        
        // Register this distribution manager with the token
        // After ExecutivePeerTreasury constructor + init(), we''re a SmartContract entity
        // so we have permission to call setDistributionManager
        IIssueToken(_issueTokenAddress).setDistributionManager(address(this));
    }
    
    /**
     * @notice Set ProjectRevenueTreasury for transfer fee notifications (same pattern as IssueToken.setDistributionManager)
     * @param _projectRevenueTreasury Address of ProjectRevenueTreasury (or address(0) to disable)
     * @dev Can only be set by SmartContract entities (PRT calls this in its constructor)
     *      Once set, onTokenTransferUpdate will notify PRT after each transfer
     * 
     * ⚠️ NOT "SET ONCE": This is intentionally updateable for operational flexibility
     *    - Only platform authority can add SmartContracts (via Controller registration)
     *    - If project has not permanently locked platform access, platform may update contracts
     *    - An update to PRT would be easier if it could repoint PRT without replacing DistributionManager
     *    - This is an "open yet secure" model: writable only by authorized SmartContracts
     * 
     * // TODO future, make IssueToken call feemanager.distribute directly and remove this method 
     *    Because feeMaanger notifies treasury already. On the other hand we only ned that notify 
     *   for transfers and this DM  is ALREADY registered so IssueToken calls back here to onTokenTransfer
     */
    function setProjectRevenueTreasury(address _projectRevenueTreasury) external {
        if (!IController(peerTreasuryController).isOfficialEntityFast(KECCAK_SMART_CONTRACT, msg.sender)) {
            revert Unauthorized();
        }
        projectRevenueTreasury = _projectRevenueTreasury;
    }

    /* ========== HOLDER TRACKING ========== */
    
    /**
     * @notice Calculate eligible supply (excludes Controller smart contract entities)
     * @dev ⚠️ CRITICAL ASSUMPTION: Controller will NEVER have more than ~15 SmartContract entities
     *      Eligible supply = totalSupply - all tokens held by official SmartContract entities
     *      This ensures distributions are only split among real holders, not locked/vesting contracts
     *      Uses cached excludedSmartContracts array (populated once on first call)
     *      
     *      If distributionSupplyBasis > 0, uses MAX(actualEligibleSupply, distributionSupplyBasis)
     *      This prevents early buyers from windfall distributions during ongoing primary sales
     * 
     * @return eligibleSupply The circulating supply available for distributions
     */
    function _calculateEligibleSupply() internal view returns (uint256 eligibleSupply) {
        IIssueToken token = IIssueToken(issueToken);
        uint256 totalSupply = token.totalSupply();
        uint256 excludedSupply = 0;
        
        // Use cached excluded contracts list (populated on first distributeToClaim or manual sync)
        for (uint256 i = 0; i < excludedSmartContracts.length; i++) {
            excludedSupply += token.balanceOf(excludedSmartContracts[i]);
        }
        
        uint256 actualEligibleSupply = totalSupply > excludedSupply ? totalSupply - excludedSupply : totalSupply;
        
        // If distributionSupplyBasis is set (> 0), use the LARGER of actual vs basis
        // This ensures early buyers don''t get windfall distributions during primary offerings
        if (distributionSupplyBasis > 0) {
            eligibleSupply = actualEligibleSupply > distributionSupplyBasis ? actualEligibleSupply : distributionSupplyBasis;
        } else {
            eligibleSupply = actualEligibleSupply;
        }
    }
    
    /**
     * @notice Get actual eligible supply (excludes smart contracts, ignores distributionSupplyBasis)
     * @dev Used internally to calculate deferred distribution amounts
     * @return actualEligibleSupply The real circulating supply
     */
    function _calculateActualEligibleSupply() internal view returns (uint256 actualEligibleSupply) {
        IIssueToken token = IIssueToken(issueToken);
        uint256 totalSupply = token.totalSupply();
        uint256 excludedSupply = 0;
        
        // Use cached excluded contracts list (populated on first distributeToClaim or manual sync)
        for (uint256 i = 0; i < excludedSmartContracts.length; i++) {
            excludedSupply += token.balanceOf(excludedSmartContracts[i]);
        }
        
        actualEligibleSupply = totalSupply > excludedSupply ? totalSupply - excludedSupply : totalSupply;
    }
    
    /**
     * @notice Sync excluded SmartContract addresses from Controller (callable by TokenAdmin)
     * @dev Fetches all SmartContract entities from Controller and caches them
     *      Should be called once after deployment, or when new system contracts are added
     *      ⚠️ ASSUMPTION: Controller has ≤15 SmartContract entities (typical: 8-12)
     */
    function syncExcludedContracts() public {
        // Only TokenAdmin or SmartContract can call (prevents griefing)
        if (!IController(peerTreasuryController).isOfficialDoubleEntityFast(
            KECCAK_TOKEN_ADMIN, msg.sender,
            KECCAK_SMART_CONTRACT, msg.sender,
            false  // OR logic
        )) revert Unauthorized();
        
        IController controller = IController(peerTreasuryController);
        
        // Clear existing cache
        delete excludedSmartContracts;
        
        // Get all SmartContract entities from Controller (one-time expensive operation)
        IController.OfficialEntityStruct[] memory smartContracts = controller.getAllOfficialEntities("SmartContract", true);
        
        // Populate cache with active SmartContract addresses
        for (uint256 i = 0; i < smartContracts.length; i++) {
            if (smartContracts[i].active) {
                excludedSmartContracts.push(smartContracts[i].pubAddress);
            }
        }
    }
    
    /**
     * @notice Harvest pending rewards for a holder at a specific balance
     * @param holder Address to harvest for
     * @param balance The balance to use for reward calculation (typically before-transfer balance)
     * @dev CRITICAL: Must be called with OLD balance before balance changes to lock in rewards
     *      Updates rewardDebt to match new accumulatedPerToken * balance
     * 
     * 🎯 DISTRIBUTION MODEL: "STICKY CLAIMS" (Real-World Dividend Model)
     * 
     * This contract implements the "sticky claims" model where distributions are LOCKED to the 
     * holder address that earned them, NOT transferred with the tokens. This aligns with real-world
     * stock dividend mechanics where dividends are paid to shareholders of record on a specific date.
     * 
     * Two Distribution Models Exist:
     * 
     * 1️⃣ STICKY CLAIMS (Our Implementation - Real-World Perfect for RWA/Equity):
     *    - Distributions locked to holder address on transfer
     *    - Seller keeps earned distributions even after selling
     *    - Buyer starts accumulating from purchase moment
     *    - Matches real-world dividend "record date" mechanics
     *    - Example: Alice earns $500, sells tokens to Bob → Alice keeps $500, Bob starts fresh
     * 
     * 2️⃣ REWARDS FOLLOW TOKEN (MasterChef/LP Farming Model):
     *    - Rewards calculated based on current balance at claim time
     *    - Seller loses unclaimed rewards when selling
     *    - Buyer inherits earning power immediately
     *    - Common in DeFi yield farming
     *    - Example: Alice earns $500, sells to Bob → Alice gets nothing, Bob can claim $500
     * 
     * Why Sticky Claims for Equity/RWA:
     * - ✅ Matches traditional finance dividend mechanics (record date precedent)
     * - ✅ Fair: holders receive proportional revenue for time held
     * - ✅ No claim pressure: sellers don''t lose earnings by forgetting to claim first
     * - ✅ Prevents gaming: buyers don''t get "free dividends" from previous holders
     * - ⚠️ Caveat: Unregistered smart contracts (non-official LPs) accumulate but can''t claim
     *   → Solution: Only official registered LPs excluded from distributions (via syncExcludedContracts)
     */
    function _harvestRewardsAtBalance(address holder, uint256 balance) internal {
        if (balance == 0) return;
        
        // Calculate pending rewards using OLD balance (SCALED by PRECISION)
        uint256 accumulated = balance * accumulatedPerToken;
        uint256 debt = rewardDebt[holder];
        if (accumulated > debt) {
            uint256 pendingScaled = accumulated - debt;
            claimableStoredScaled[holder] += pendingScaled;
        }

        // Update debt to current accumulated for this balance
        rewardDebt[holder] = balance * accumulatedPerToken;
    }

    /**
     * @notice Reset reward debt when holder no longer holds tokens
     * @dev Does NOT touch claimableStored (no forfeiture).
     */
    // NOTE: balance going to 0 does NOT clear claimableStoredScaled. We only clear rewardDebt.
    
    /**
     * @notice Called by IssueToken on every transfer to track holder status
     * @param from Sender address (address(0) for mints)
     * @param to Recipient address (address(0) for burns)
     * @param value Amount transferred
     * @param fromBalanceBefore Sender''s balance before transfer (passed from token for gas efficiency)
     * @param toBalanceBefore Recipient''s balance before transfer (passed from token for gas efficiency)
     * @dev Only callable by the bound IssueToken contract
     *      Before balances passed from token = single source of truth (no shadow state drift)
     *      Tracks when holders go from 0 → non-zero (activate) or non-zero → 0 (deactivate)
     *      🔑 CRITICAL: Harvests rewards using BEFORE balances to lock in amounts
     *  key: ontransferupdate  onupdatetransfer 
     */
    function onTokenTransferUpdate(
        address from,
        address to,
        uint256 value,
        uint256 fromBalanceBefore,
        uint256 toBalanceBefore
    ) external onlyToken {
        // Handle sender (if not mint)
        if (from != address(0)) {
            // Harvest rewards at OLD balance (passed from token)
            _harvestRewardsAtBalance(from, fromBalanceBefore);
            
            uint256 fromBalanceAfter = fromBalanceBefore - value;
            
            // Update rewardDebt for NEW balance (reset to 0 if they no longer hold)
            if (fromBalanceAfter == 0) {
                delete rewardDebt[from];
            } else {
                rewardDebt[from] = fromBalanceAfter * accumulatedPerToken;
            }
            
            // Check for deactivation: non-zero → zero
            if (fromBalanceBefore > 0 && fromBalanceAfter == 0) {
                if (activeHolderCount > 0) {
                    activeHolderCount--;
                }
            }
        }
        
        // Handle recipient (if not burn)
        if (to != address(0)) {
            // Harvest rewards at OLD balance (passed from token)
            _harvestRewardsAtBalance(to, toBalanceBefore);
            
            uint256 toBalanceAfter = toBalanceBefore + value;
            
            // Update rewardDebt for NEW balance
            rewardDebt[to] = toBalanceAfter * accumulatedPerToken;
            
            // Check for activation: zero → non-zero
            if (toBalanceBefore == 0 && toBalanceAfter > 0) {
                activeHolderCount++;
            }
        }
        
        // 🚀 AUTO-DISTRIBUTE: If available balance exceeds threshold, auto-allocate to claims
        if (autoDistributeThreshold > 0) {
            // Calculate available = balanceOf(this) - totalOwedAmounts (READ ONCE for efficiency)
            uint256 actualBalance = IERC20(stableCoinAddress).balanceOf(address(this));
            uint256 available = actualBalance > totalOwedAmounts ? actualBalance - totalOwedAmounts : 0;
            
            if (available >= autoDistributeThreshold) {
                // Call INTERNAL method directly to avoid redundant balanceOf() call (~2,600 gas savings)
                // Already calculated ''available'' above, pass it directly for validation
                // Note: No try/catch needed - if this reverts, it''s a contract bug that should fail loudly
                _distributeToClaim(available, available);
            }
        }
        
        // 🔔 NOTIFY ProjectRevenueTreasury: Trigger after every transfer (best-effort, never reverts)
        // PRT.onTransferFeeDistributed() -> processRevenueAndDisperse() -> settleHolderFees()
        // This ensures PRT maintains healthy reserves and holder fee obligations
        //
        // IMPORTANT: We swallow all errors EXCEPT when PRT is short stablecoin for holder fees.
        // In that specific case, we block transfers UNLESS the recipient is an official SmartContract.
        if (projectRevenueTreasury != address(0)) {
            try IProjectRevenueTreasury(projectRevenueTreasury).onTransferFeeDistributed() {
                // ok
            } catch (bytes memory data) {
                // Detect ProjectRevenueTreasury.InsufficientTreasuryBalance()
                bytes4 sel;
                if (data.length >= 4) {
                    assembly { sel := mload(add(data, 32)) }
                }
                bytes4 insuffSel = bytes4(keccak256("InsufficientTreasuryBalance()"));
                if (sel == insuffSel) {
                    // Allow transfers TO official SmartContracts even when treasury is unfunded
                    uint256 codeSize;
                    assembly { codeSize := extcodesize(to) }
                    bool toIsOfficialSC = (codeSize > 0) &&
                        IController(peerTreasuryController).isOfficialEntityFast(KECCAK_SMART_CONTRACT, to);
                    if (!toIsOfficialSC) {
                        revert("Project has insufficient treasury for holder fees. Transfers disabled.");
                    }
                }
                // Swallow all other errors as normal
            }
        }
    }
    

    /* ========== CLAIM-BASED DISTRIBUTION ========== */
    
    /**
     * @notice Internal distribution logic (gas-optimized for internal calls)
     * @param totalAmount Total stablecoin to allocate
     * @param availableBalance Pre-calculated available balance (contractBalance - totalOwedAmounts)
     * @dev INTERNAL ONLY - caller must pre-calculate and pass availableBalance to avoid redundant external calls
     *      This pattern saves ~2,600 gas by avoiding duplicate stableCoin.balanceOf() calls
     *      
     *      Used by:
     *      - onTokenTransferUpdate: auto-distribute (already calculated balance for threshold check)
     *      - distributeToClaim: external entry point (calculates balance once and passes here)
     * 
     * @return totalAllocated The total amount allocated
     */
    function _distributeToClaim(uint256 totalAmount, uint256 availableBalance) 
        internal 
        returns (uint256 totalAllocated) 
    {
        // Validate using pre-calculated balance (no re-read of stableCoin.balanceOf!)
        if (availableBalance < totalAmount) revert InsufficientBalance();
        
        // Sync excluded contracts on first distribution if not yet populated
        if (excludedSmartContracts.length == 0) {
            syncExcludedContracts();
        }
        
        // Calculate eligible supply (totalSupply - smart contract holdings)
        // If distributionSupplyBasis > 0, this returns MAX(actual, basis)
        uint256 eligibleSupply = _calculateEligibleSupply();
        if (eligibleSupply == 0) revert NoActiveHolders();
        
        // 🚀 THE MAGIC: Update global accumulated per token (O(1) gas!)
        // Each token now has: (totalAmount * PRECISION) / eligibleSupply more claimable value
        // Note: Uses eligibleSupply (which may be distributionSupplyBasis if > actual)
        uint256 perTokenIncrease = (totalAmount * PRECISION) / eligibleSupply;
        accumulatedPerToken += perTokenIncrease;
        
        // Calculate ACTUAL allocation (what real holders can claim)
        uint256 actualEligibleSupply = _calculateActualEligibleSupply();
        uint256 actualAllocated = (perTokenIncrease * actualEligibleSupply) / PRECISION;
        
        // Lock the actual allocated amount in this contract
        totalOwedAmounts += actualAllocated;
        
        // If distributionSupplyBasis is set and actual < basis, transfer deferred amount to IssueToken treasury
        if (distributionSupplyBasis > 0 && actualEligibleSupply < distributionSupplyBasis) {
            uint256 effectiveTotal = (perTokenIncrease * eligibleSupply) / PRECISION;
            uint256 deferredAmount = effectiveTotal - actualAllocated;
            
            if (deferredAmount > 0) {
                // Transfer deferred distribution to IssueToken treasury for future handling
                IERC20(stableCoinAddress).safeTransfer(issueToken, deferredAmount);
                
                emit DeferredDistributionToTokenTreasury(
                    deferredAmount,
                    actualEligibleSupply,
                    distributionSupplyBasis,
                    block.timestamp
                );
            }
        }
        
        // Emit event based on caller type (SmartContract = auto-distribute, otherwise = manual)
        if (IController(peerTreasuryController).isOfficialEntityFast(KECCAK_SMART_CONTRACT, msg.sender)) {
            emit AutoDistributeTriggered(actualAllocated, block.timestamp);
        } else {
            emit DistributionAllocated(
                msg.sender,
                actualAllocated,
                perTokenIncrease,
                block.timestamp
            );
        }
        
        return actualAllocated;
    }
    
    /**
     * @notice Allocate stablecoin PROPORTIONALLY to all active holders'' claimable amounts (EXTERNAL entry point)
     * @dev Does NOT transfer - holders must call claim() to collect
     * @param totalAmount Total stablecoin to allocate (in STABLECOIN decimals, e.g., 1000000 = $1 USDC with 6 decimals)
     * 
     *      🎯 CLAIM MODEL: This function does NOT transfer - it only updates accumulatedPerToken
     *      Holders must call claim() to collect. This prevents malicious contracts from blocking distributions.
     *      Smart contracts CAN participate - they handle their own receive() logic.
     *      
     *      🚀 O(1) GAS COST: Only updates ONE global variable regardless of holder count!
     *      
     *      Distribution formula:
     *        perTokenIncrease = (totalAmount * PRECISION) / totalSupply
     *        accumulatedPerToken += perTokenIncrease
     *        holderClaimable = (balance * accumulatedPerToken - rewardDebt) / PRECISION
     *      
     *      🔒 LOCKED FUNDS: totalOwedAmounts is increased and protected from admin withdrawal
     *      
     *      🛡️ SAFETY: Always validates available balance (contractBalance - totalOwedAmounts)
     *      This ensures solvency even if called multiple times (not idempotent by design)
     *      
     *      💡 GAS OPTIMIZATION: Calculates balance once and delegates to internal _distributeToClaim
     *      This avoids redundant external calls when used by onTokenTransferUpdate
     *      
     * @return totalAllocated The total amount allocated
     */
    function distributeToClaim(uint256 totalAmount) 
        external 
        returns (uint256 totalAllocated) 
    {
        // Allow SmartContract (for auto-distribute) OR TreasuryAdmin (for manual distribute)
        if (!IController(peerTreasuryController).isOfficialDoubleEntityFast(
            KECCAK_SMART_CONTRACT, msg.sender,
            KECCAK_TREASURY_ADMIN, msg.sender,
            false  // OR logic
        )) revert Unauthorized();
        
        // Calculate available balance ONCE (gas optimization)
        uint256 contractBalance = IERC20(stableCoinAddress).balanceOf(address(this));
        uint256 available = contractBalance > totalOwedAmounts 
            ? contractBalance - totalOwedAmounts 
            : 0;
        
        // Delegate to internal method (passes pre-calculated balance to avoid re-reading)
        return _distributeToClaim(totalAmount, available);
    }
    
    /**
     * @notice Claim accumulated distributions
     * @dev Anyone can call to claim their own distributions
     *      Uses rewardDebt pattern: owed = (balance * accumulatedPerToken) - rewardDebt
     *      EOAs pay their own gas - they decide when it''s worth claiming
     *      Smart contracts CAN claim too - they handle their own receive() logic
     * @return amount Amount claimed
     */
    function claim() external nonReentrant returns (uint256 amount) {
        uint256 balance = IIssueToken(issueToken).balanceOf(msg.sender);
        
        // If they still hold tokens, harvest pending into stored bucket first (CEI)
        // If balance == 0, they can still claim whatever is already stored (no forfeiture).
        if (balance > 0) {
            _harvestRewardsAtBalance(msg.sender, balance);
        }

        uint256 storedScaled = claimableStoredScaled[msg.sender];
        amount = storedScaled / PRECISION; // stablecoin decimals (integer)
        if (amount == 0) revert AmountTooLow();

        // Effects first (CEI)
        // Keep remainder (dust) for future claims
        claimableStoredScaled[msg.sender] = storedScaled - (amount * PRECISION);

        // Reduce locked amount
        totalOwedAmounts -= amount;

        // Transfer claimed amount
        IERC20(stableCoinAddress).safeTransfer(msg.sender, amount);
        
        emit Claimed(msg.sender, amount, block.timestamp);
        
        return amount;
    }
    
    /**
     * @notice Check claimable amount for any address
     * @param holder Address to check
     * @return amount Claimable amount in stablecoin decimals
     */
    function getClaimableAmount(address holder) external view returns (uint256 amount) {
        uint256 storedScaled = claimableStoredScaled[holder];
        uint256 balance = IIssueToken(issueToken).balanceOf(holder);
        if (balance == 0) return storedScaled / PRECISION;

        // stored + pending
        uint256 pendingScaled = 0;
        {
            uint256 accumulated = balance * accumulatedPerToken;
            uint256 debt = rewardDebt[holder];
            if (accumulated > debt) {
                pendingScaled = accumulated - debt;
            }
        }
        return (storedScaled + pendingScaled) / PRECISION;
    }

    /**
     * @notice Allocate specific percentage of contract''s available stablecoin balance to claimable amounts
     * @param percentageBps Percentage in basis points (e.g., 5000 = 50%)
     * @return totalAllocated Actual amount allocated
     * @dev Gas-optimized: Calculates available balance once and uses internal _distributeToClaim
     */
    function distributePercentageToClaim(uint256 percentageBps) 
        external 
        onlyTreasuryOrSCAdmin 
        returns (uint256 totalAllocated) 
    {
        require(percentageBps <= 10000, "Percentage cannot exceed 100%");
        
        // Calculate available balance ONCE (gas optimization)
        uint256 contractBalance = IERC20(stableCoinAddress).balanceOf(address(this));
        uint256 available = contractBalance > totalOwedAmounts 
            ? contractBalance - totalOwedAmounts 
            : 0;
        
        uint256 amountToDistribute = (available * percentageBps) / 10000;
        
        // Use internal method to avoid redundant balanceOf() call (~2,600 gas savings)
        return _distributeToClaim(amountToDistribute, available);
    }

    /* ========== ADMIN FUNCTIONS ========== */
    
    
    /**
     * @notice Update maximum holder count for auto-sync on distributeToClaim
     * @param newMaxCount New maximum holder count (0 = disable auto-sync)
     * @dev If IssueToken.getHolderCount() <= this value, distributeToClaim() will auto-sync
     *      Default is 100. Set higher for more safety, lower for less gas.
     *      Set to 0 to disable auto-sync entirely.
     */
    
    /**
     * @notice Enable/disable auto-distribute by setting minimum payout threshold
     * @param minPayoutThreshold Minimum balance to trigger auto-distribute
     *        - Set to 0 to DISABLE auto-distribute (manual distributeToClaim only)
     *        - Set to >= 10 to ENABLE auto-distribute (triggers on transfers when threshold met)
     * @dev Only TreasuryAdmin can change this
     *      Reverts if set to 1-9 (prevents excessive gas costs from frequent auto-distributes)
     *      Example: 1000000000 = $1000 USDC (6 decimals) - reasonable for most projects
     */
    function setAutoDistributeThreshold(uint256 minPayoutThreshold) external onlyTreasuryOrSCAdmin {
        // Allow 0 (disabled) or >= 10 (enabled with reasonable minimum)
        // Prevent 1-100 to avoid triggering auto-distribute on every tiny transfer
        if (minPayoutThreshold > 0 && minPayoutThreshold < 100) {
            revert ThresholdTooLow();
        }
        
        autoDistributeThreshold = minPayoutThreshold;
        emit AutoDistributeThresholdUpdated(minPayoutThreshold);
    }
    
    /**
     * @notice Update distribution supply basis for ongoing primary offerings
     * @param newDistributionSupplyBasis Expected total circulating supply for fair distribution calculations
     *        - Set to 0 to DISABLE (uses actual eligible supply only, normal behavior)
     *        - Set to > 0 to ENABLE (prevents early buyer windfall during primary sales)
     * @dev Only TreasuryAdmin or SCAdmin can change this
     *      When enabled, distributions use MAX(actualEligibleSupply, distributionSupplyBasis) as denominator
     *      Deferred amounts (difference between expected vs actual allocation) transfer to IssueToken treasury
     *      Example: Set to 1000000e18 for expected 1M token final supply during ongoing token sales
     */
    function setDistributionSupplyBasis(uint256 newDistributionSupplyBasis) external onlyTreasuryOrSCAdmin {
        distributionSupplyBasis = newDistributionSupplyBasis;
        emit DistributionSupplyBasisUpdated(newDistributionSupplyBasis);
    }

    /* ========== SYNCHRONIZATION (FOR LATE DEPLOYMENT) ========== */
    
    // REMOVED: syncBalances() and autoSync() functions
    // No longer needed - onTokenTransferUpdate maintains activeHolderCount correctly on every transfer
    // If deployed late, activeHolderCount will build up from 0 as transfers occur
    // For immediate accuracy, call distributeToClaim() which checks eligibleSupply (works even if deployed late)
    
    /* ========== VIEW FUNCTIONS ========== */
    
    /**
     * @notice Get active holder count (only holders with non-zero balance)
     * @dev This is maintained automatically on every transfer
     *      If deployed late, this will be 0 initially and build up as transfers occur
     */
    function getActiveHolderCount() external view returns (uint256) {
        return activeHolderCount;
    }
    
    /**
     * @notice Preview distribution details for a given total amount
     * @param totalAmount Total amount to allocate
     * @return perTokenIncrease How much the accumulatedPerToken would increase
     * @dev In O(1) claim model, distribution just updates one global variable
     *      Each holder''s claimable increases by: balance * perTokenIncrease / PRECISION
     */
    function previewDistribution(uint256 totalAmount) 
        external 
        view 
        returns (uint256 perTokenIncrease) 
    {
        uint256 eligibleSupply = _calculateEligibleSupply();
        if (eligibleSupply == 0) return 0;
        
        perTokenIncrease = (totalAmount * PRECISION) / eligibleSupply;
    }
    
    /**
     * @notice Get the current eligible supply (excludes smart contract entities)
     * @return eligibleSupply The circulating supply available for distributions
     */
    function getEligibleSupply() external view returns (uint256 eligibleSupply) {
        return _calculateEligibleSupply();
    }

    /**
     * @notice Get contract''s stablecoin balance available for distribution
     * @dev Available = balanceOf(this) - totalOwedAmounts
     *      This is what can be distributed or withdrawn by admin
     */
    function getAvailableBalance() public view returns (uint256) {
        uint256 actualBalance = IERC20(stableCoinAddress).balanceOf(address(this));
        return actualBalance > totalOwedAmounts ? actualBalance - totalOwedAmounts : 0;
    }
    
    /* ========== WITHDRAWAL OVERRIDES (PROTECT LOCKED FUNDS) ========== */
    
    /**
     * @notice Override to prevent withdrawal of owed distributions
     * @dev Follows ProjectRevenueTreasury pattern: protects totalOwedAmounts
     */
    function peerTreasuryTransferTokens(address token, address to, uint256 amount) public override onlyTreasuryOrSCAdmin {
        if (token == stableCoinAddress) {
            uint256 actualBalance = IERC20(stableCoinAddress).balanceOf(address(this));
            uint256 maxWithdrawable = actualBalance > totalOwedAmounts ? actualBalance - totalOwedAmounts : 0;
            require(amount <= maxWithdrawable, "Cannot withdraw owed distributions");
        }
        super.peerTreasuryTransferTokens(token, to, amount);
    }
    
    /**
     * @notice Override to prevent withdrawal of owed distributions
     * @dev Follows ProjectRevenueTreasury pattern: protects totalOwedAmounts
     */
    function peerTreasuryTransferTokensDirect(address token, address to, uint256 amount) public override onlyTreasuryOrSCAdmin {
        if (token == stableCoinAddress) {
            uint256 actualBalance = IERC20(stableCoinAddress).balanceOf(address(this));
            uint256 maxWithdrawable = actualBalance > totalOwedAmounts ? actualBalance - totalOwedAmounts : 0;
            require(amount <= maxWithdrawable, "Cannot withdraw owed distributions");
        }
        super.peerTreasuryTransferTokensDirect(token, to, amount);
    }
    
    /**
     * @notice Override ExecutivePeerTreasury withdrawal to protect owed distributions
     * @dev Cannot withdraw stablecoin if it would reduce balance below totalOwedAmounts
     *      Only TreasuryAdmin or SCAdmin can withdraw  (see super version for more details)
     */
    function executiveWithdrawTokens(address personAddress, uint256 amt, address tokenSCAddress, string calldata note) public override {
        if (tokenSCAddress == stableCoinAddress) {
            uint256 actualBalance = IERC20(stableCoinAddress).balanceOf(address(this));
            uint256 maxWithdrawable = actualBalance > totalOwedAmounts ? actualBalance - totalOwedAmounts : 0;
            require(amt <= maxWithdrawable, "Cannot withdraw owed distributions");
        }
        super.executiveWithdrawTokens(personAddress, amt, tokenSCAddress, note);
    }
}

