contract RiskyParentContract {
    function isContract(address account) internal view returns (bool) {
        return account.code.length > 0;
    }

    function internalDelegateCall(
        address target,
        bytes memory data
    ) internal returns (bytes memory) {
        (, bytes memory returndata) = target.delegatecall(data);
        return returndata;
    }

    function privateDelegateCall(
        address target,
        bytes memory data
    ) private returns (bytes memory) {
        (, bytes memory returndata) = target.delegatecall(data);
        return returndata;
    }
}', '2025-07-18 15:51:18.643275+00', '2025-07-18 15:51:18.643275+00', 'sourcify', 'sourcify');
