     * @return The derived seed.
     */
    function _getSeed(
        uint256 id,
        bytes32 entropy
    ) internal view returns (bytes32) {
        // Return seed using id, entropy, & token creator as determinants.
        return (
            keccak256(
                abi.encodePacked(id, entropy)
