INSERT INTO sources (source_hash, source_hash_keccak, content, created_at, updated_at, created_by, updated_by) VALUES ('\x32b5e0847d1d1d142c79c1686808a2c1d695d4e6d2db24b1d3d1df8ddb6df5d4', '\xc33fdb31cee89ac77dfaf9fc3cbe2277655cc934b13d5caaa90aa644e43076b3', '// SPDX-License-Identifier: MIT
pragma solidity ^0.8.9;

import "./RiskyParentContract.sol";

contract SafeRecursion is RiskyParentContract {
    function safe(uint256 i) public view returns (bool) {
        if (++i == 10) {
            return isContract(address(this));
        } else {
            return safe(i);
        }
    }
}
