INSERT INTO sources (source_hash, source_hash_keccak, content, created_at, updated_at, created_by, updated_by) VALUES ('\x4f5a55924b1ed6d05bfd0bdee9f0741cd73a638dc6d6124cc840c7e831dcb663', '\x617614c3aaada8d7a901da2126a7407ae7e06b0410807f5c1b49cea9076199e9', '// SPDX-License-Identifier: MIT

