INSERT INTO sources (source_hash, source_hash_keccak, content, created_at, updated_at, created_by, updated_by) VALUES ('\x832589b4bf9cc49f0d2f0b4370c9e6e6ca4f3123d1364126b607d73800153a01', '\xaed0d623400da9de16345988cdfb9e8432e2e92ec0eacd12a036a185cb6377ff', '// SPDX-License-Identifier: MIT
