INSERT INTO sources (source_hash, source_hash_keccak, content, created_at, updated_at, created_by, updated_by) VALUES ('\x97a8d607694194b6de26c0a15d9439394748e8157fa38813bc7614f7d2e4ba67', '\x8c4c1b8e724e0a78cb691d703dd37cd91b8bd6600537fb227807a194025a792d', '// SPDX-License-Identifier: GPL-2.0-or-later
