// across the EquityMint ecosystem with TreasuryAdmin and Super role enforcement integrated with Controller.
// 
// Chief Architect and CEO: Ken Silverman, US Fintech LLC
// Designed by Ken Silverman as part of the EquityMint treasury infrastructure.
// @author Ken Silverman
// 
// ⚖️  AUTHORIZED USE RESTRICTIONS:
// Only projects deploying these contracts via the EquityMint platform at equitymint.org 
// which contain this preamble and Fee structures generated through EquityMint.org have 
// permission to use these contracts or any derivative works thereto. Any such deployment 
// must contain these words. This contract is part of a greater system. They are owned 
// and licensed exclusively in writing and through US Fintech, LLC. 
// 
// Any breach of these terms will be investigated and pursued through all available civil 
// and criminal remedies to the fullest extent permitted by applicable law. Enforcement is 
// discretionary. The failure to enforce any provision shall not constitute a waiver of the 
// right to enforce at any time. All projects and platform users interacting with this system 
// are subject to additional terms and conditions as may be published or updated from time to 
// time at https://equitymint.org and/or https://DataCloudOS.com.
pragma solidity 0.8.30;

import "../interfaces/IController.sol";
import "../interfaces/IFeeManager.sol";
import "./TreasuryConstants.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

// Earlier versions Compiled by Maleeha Naveed. May 5th, 2025
// ExecutivePeerTreasury is a contract that allows for the transfer of ETH and ERC20 tokens between different contracts.
/// @author Ken Silverman 
// - first decentralized RWA management architect, est. 2017.
contract ExecutivePeerTreasury is TreasuryConstants {

    using SafeERC20 for IERC20;
    
    event PeerTreasuryReceivedETH(address indexed sender, uint256 amount);
    event PeerTreasuryReceivedTokens(address indexed sender, address indexed token, uint256 amount);
    event PeerTreasuryTransferredETH(address indexed to, uint256 amount);
    event PeerTreasuryTransferredTokens(address indexed to, address indexed token, uint256 amount);
    event ExecutiveWithdrawalEvent(address indexed adminCaller, address indexed receiver, uint256 amt, string note, address tokenOrZero);
    event StableCoinAddressChanged(address newStableCoinAddress, address indexed changedBy);


    struct TreasuryEntry {
        uint256 totalReceived;
        uint256 totalWithdrawn;
    }

    struct Withdrawal{
        address to;
        address asset;
        uint256 amt;
        string note;
    }

    address public immutable peerTreasuryController;
    address public immutable feeManager;
    address public immutable issueTokenAddress;
    address public stableCoinAddress; // Not immutable - can be set by children or via setter

    mapping(address => TreasuryEntry) private tokenPeerTreasury;
    address[] internal knownTokens; // <-- Needed for enumeration

    TreasuryEntry private ethPeerTreasury;
    Withdrawal[] private withdrawals; // Track all executive withdrawals

    error LowEthBal();
    error LowTokenBal();
    error SenderNotOfficialSC();
    error RecipientNotOfficialSC();
    error InvalidController();
    error ETHTransferFailed();
    error InvalidTokenAddress();
    error InsufficientUSDCForFees();
    error NoETHSent();
    error ZeroAmount();
    error InvalidAddress();

    modifier onlyTreasuryOrSCAdmin() {
        require(
            IController(peerTreasuryController).isOfficialDoubleEntityFast(KECCAK_TREASURY_ADMIN, msg.sender, KECCAK_SMART_CONTRACT, msg.sender, false),
            "Unauthorized"
        );
        _;
    }

    constructor(
        address _controller,
        address _feeManager,
        address _issueToken,
        string memory _contractName
    ) {
        if (_controller == address(0)) revert InvalidController();
        
        peerTreasuryController = _controller;
        feeManager = _feeManager;
        issueTokenAddress = _issueToken;
        
        // Get stablecoin address from IssueToken (if provided)
        // Skip if _issueToken == address(this) (called from IssueToken''s own constructor - can''t query self yet)
        // IssueToken will set its own stableCoinAddress in its constructor body after parent runs
        if (_issueToken != address(0) && _issueToken != address(this)) {
            (bool success, bytes memory data) = _issueToken.staticcall(
                abi.encodeWithSignature("stableCoinAddress()")
            );
            if (success && data.length == 32) {
                stableCoinAddress = abi.decode(data, (address));
            }
        }
        
        IController(_controller).init(address(this), _contractName);
    }

    // EMERGENCY withdraw for admin controlled DIRECT withdrawals to a PERSON (not a smart contract)
    // this can ONLY happen for example, when the company wants to send some USDC or ETH from the Sales contract
    // to an EXECUTIVE of the company for the purposes of exchanging to USDC, as an example.
    // Such USDC can be spent on a capital expense or manually passed into the vesting pool.
    // ONLY HUBS can do this. For example, only contracts GENERATING or expected to RECEIVE
    // ETH or tokens from an external event (not from a HUB)  should be declared as HUBS.
    // EXCEPTIONS: send tokens to a launchpad or other noted entity can be a SC.
    function executiveWithdrawETH(address personAddress, uint256 amt, string memory note) external onlyTreasuryOrSCAdmin {
        if (address(this).balance < amt) revert LowEthBal();
        (bool success, ) = payable(personAddress).call{value: amt}("");
        if (!success) revert ETHTransferFailed();
        ethPeerTreasury.totalWithdrawn += amt;
        withdrawals.push(Withdrawal(personAddress,address(0),amt,note));
        emit ExecutiveWithdrawalEvent(msg.sender, personAddress, amt, note, address(0));
    }

    function executiveWithdrawTokens(address personAddress, uint256 amt, address tokenSCAddress, string calldata note) public virtual onlyTreasuryOrSCAdmin {
        if (tokenSCAddress == address(0)) revert InvalidTokenAddress();
        IERC20 token = IERC20(tokenSCAddress);
        if (token.balanceOf(address(this)) < amt) revert LowTokenBal();
        
        // If withdrawing IssueToken, manually collect transfer fees (like holder fees in PRT)
        // Transfer itself will be fee-exempt (SmartContract → User), but we collect fees anyway
        if (tokenSCAddress == issueTokenAddress && feeManager != address(0)) {
            // pass 0 value, no percent TRANSFERfees possible.
            // without saleManager, NAVPool or LP price. Absolute fees only.
            // TODO next version get from NAV last price with SaleManger or LP last price fallback
            // Passing 0 instead of tokenAmount, still preserves absolute TRANSFER fees  
            (IFeeManager.CalculatedEntityAmount[] memory fees, uint256 totalFee) = 
                IFeeManager(feeManager).calculateChainedAmounts(0, 10000, keccak256("Transfer"));
            
            if (totalFee > 0) {
                // Distribute fees by pulling from msg.sender (same as IssueToken transfer fees)
                for (uint256 i = 0; i < fees.length; i++) {
                    if (fees[i].amount > 0) {
                        IERC20(stableCoinAddress).safeTransferFrom(msg.sender, fees[i].entityAddress, fees[i].amount);
                    }
                }
            }
        }
        
        // Execute token transfer (fee-exempt since we''re a SmartContract)
        IERC20(tokenSCAddress).safeTransfer(personAddress, amt);
        tokenPeerTreasury[tokenSCAddress].totalWithdrawn += amt;
        withdrawals.push(Withdrawal(personAddress,tokenSCAddress,amt,note));
        emit ExecutiveWithdrawalEvent(msg.sender, personAddress, amt, note, tokenSCAddress);
    }

    /// @notice Receive ETH from any source and track it
    function peerTreasuryReceiveETH() virtual external payable {
        if (msg.value == 0) revert NoETHSent();
        if (!IController(peerTreasuryController).isOfficialEntityFast(KECCAK_SMART_CONTRACT, msg.sender)) revert SenderNotOfficialSC();
        ethPeerTreasury.totalReceived += msg.value;
        emit PeerTreasuryReceivedETH(msg.sender, msg.value);
    }

    /// @notice Transfer ETH to another peer contract (OfficialEntity SmartContract)
    function peerTreasuryTransferETH(address payable to, uint256 amount) virtual public onlyTreasuryOrSCAdmin {
        if (address(this).balance < amount) revert LowEthBal();
        if (!IController(peerTreasuryController).isOfficialEntityFast(KECCAK_SMART_CONTRACT, to)) revert RecipientNotOfficialSC();
        ethPeerTreasury.totalWithdrawn += amount;
        ExecutivePeerTreasury(to).peerTreasuryReceiveETH{value: amount}();
        emit PeerTreasuryTransferredETH(to, amount);
    }

    /// @notice Receive ERC20 tokens and track source
    function peerTreasuryReceiveTokens(address token, uint256 amount) virtual external {
        if (amount == 0) revert ZeroAmount();
        if (!IController(peerTreasuryController).isOfficialEntity("SmartContract", msg.sender)) revert SenderNotOfficialSC();
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);

        // Track the token if it''s the first time we''re seeing it
        if (tokenPeerTreasury[token].totalReceived == 0 && tokenPeerTreasury[token].totalWithdrawn == 0) {
            knownTokens.push(token);
        }

        tokenPeerTreasury[token].totalReceived += amount;
        emit PeerTreasuryReceivedTokens(msg.sender, token, amount);
    }

    /// @notice Transfer ERC20 tokens to another peer contract (OfficialEntity SmartContract)
    function peerTreasuryTransferTokens(address token, address to, uint256 amount) virtual public onlyTreasuryOrSCAdmin {
        if (IERC20(token).balanceOf(address(this)) < amount) revert LowTokenBal();
        if (!IController(peerTreasuryController).isOfficialEntityFast(KECCAK_SMART_CONTRACT, to)) revert RecipientNotOfficialSC();
        tokenPeerTreasury[token].totalWithdrawn += amount;
         // Get current allowance and reset to zero using decrease
        uint256 currentAllowance = IERC20(token).allowance(address(this), to);
        if (currentAllowance > 0) {
            IERC20(token).safeDecreaseAllowance(to, currentAllowance);
        }
        // Set new allowance using increase
        IERC20(token).safeIncreaseAllowance(to, amount);
        ExecutivePeerTreasury(to).peerTreasuryReceiveTokens(token, amount);
        emit PeerTreasuryTransferredTokens(to, token, amount);
    }

    /// @notice Check ETH available (total received - total withdrawn)
    /// @return The signed balance (can be negative if more was withdrawn than received - which is OK!)
    /// obviously the first lateral movement will be a withdrawal from a peerTreasury source
    function peerETHAvailable() external view returns (int256) {
        // Convert to int256 before subtraction to allow negative results
        return int256(ethPeerTreasury.totalReceived) - int256(ethPeerTreasury.totalWithdrawn);
    }

    /// @notice Check token available (total received - total withdrawn)
    /// @return The signed balance (can be negative if more was withdrawn than received)
    /// obviously the first lateral movement will be a withdrawal from a peerTreasury source
    function peerTokenAvailable(address token) external view returns (int256) {
        TreasuryEntry storage e = tokenPeerTreasury[token];
        // Convert to int256 before subtraction to allow negative results
        return int256(e.totalReceived) - int256(e.totalWithdrawn);
    }

    struct TreasurySnapshot {
        address token;
        uint256 totalReceived;
        uint256 totalWithdrawn;
    }


    /// @notice Return all known peer treasury token entries
   function getPeerTreasuries() external view returns (TreasurySnapshot[] memory) {
        uint256 len = knownTokens.length;
        TreasurySnapshot[] memory result = new TreasurySnapshot[](len);
        for (uint256 i = 0; i < len; i++) {
            address token = knownTokens[i];
            TreasuryEntry storage entry = tokenPeerTreasury[token];

            result[i] = TreasurySnapshot({
                token: token,
                totalReceived: entry.totalReceived,
                totalWithdrawn: entry.totalWithdrawn
            });
        }
        return result;
    }

    /// @notice Return individual peer treasury entry for a token
    function getPeerTreasury(address token) external view returns (uint256 received, uint256 withdrawn) {
        TreasuryEntry storage entry = tokenPeerTreasury[token];
        return (entry.totalReceived, entry.totalWithdrawn);
    }

    /// @notice Return ETH treasury data
    function getPeerTreasuryETH() external view returns (uint256 received, uint256 withdrawn) {
        return (ethPeerTreasury.totalReceived, ethPeerTreasury.totalWithdrawn);
    }

    function getAllWithdrawals() external view returns(Withdrawal[] memory){
        return withdrawals;
    }

    
    
    // SAFE DIRECT METHODS
    /// @notice DIRECT TOKEN TRANSFER - Transfer tokens directly without approve/transferFrom pattern
    /// @param token Token contract address
    /// @param to Recipient PeerTreasury contract
    /// @param amount Amount to transfer
    function peerTreasuryTransferTokensDirect(address token, address to, uint256 amount) virtual public onlyTreasuryOrSCAdmin {
        if (IERC20(token).balanceOf(address(this)) < amount) revert LowTokenBal();
        if (!IController(peerTreasuryController).isOfficialEntityFast(KECCAK_SMART_CONTRACT, to)) revert RecipientNotOfficialSC();
        // Update withdrawal tracking
        tokenPeerTreasury[token].totalWithdrawn += amount;
        // Direct transfer - handles USDT properly
        IERC20(token).safeTransfer(to, amount);
        // Notify receiver for tracking (no actual transfer needed)
        ExecutivePeerTreasury(to).peerTreasuryNotifyReceived(token, amount);
        emit PeerTreasuryTransferredTokens(to, token, amount);
    }

    /// @notice NOTIFICATION METHOD - Update counters when tokens received via direct transfer
    /// @param token Token contract address  
    /// @param amount Amount received
    function peerTreasuryNotifyReceived(address token, uint256 amount) virtual public {
        if (!IController(peerTreasuryController).isOfficialEntityFast(KECCAK_SMART_CONTRACT, msg.sender)) revert SenderNotOfficialSC();
        // Update received tracking (same as peerTreasuryReceiveTokens but no transferFrom)
        tokenPeerTreasury[token].totalReceived += amount;
        // tokenPeerTreasury[token].currentBalance += amount;
        emit PeerTreasuryReceivedTokens(msg.sender, token, amount);
    }

    /// @notice Receive ETH fees from FeeManager (ultra-lightweight, no accounting)
    /// @dev ONLY for FeeManager → ProjectRevenueTreasury ETH fee distribution
    ///      Does NOT update totalReceived (reserved for peer-to-peer transfer accounting)
    ///      Does NOT emit events (gas optimization)
    ///      ⚠️ Use peerTreasuryReceiveETH() for tracked peer transfers that trigger downstream logic
    ///      ⚠️ NORMAL OPERATION: Funds received via this method are NOT auto-deployed
    ///         They accumulate in treasury balance until processRevenueAndDisperse() is called
    function receiveFee() external payable {
        // Just accept ETH - no tracking or events
    }

    /// @notice Set or update the stablecoin address used for fee payments
    /// @param newStableCoinAddress New stablecoin contract address (e.g., USDC)
    /// @dev Can only be called by PlatformTreasurer
    ///      Updates stableCoinAddress for this contract and all children can access it
    ///      Made public virtual so IssueToken can override with super.setStableCoinAddress()
    function setStableCoinAddress(address newStableCoinAddress) public virtual {
        if (!IController(peerTreasuryController).isOfficialEntityFast(KECCAK_TOKEN_ADMIN, msg.sender)) revert NotTokenAdmin();
        if (!IController(peerTreasuryController).isPlatformAdmin(newStableCoinAddress, KECCAK_OFFICIAL_STABLECOIN)) revert InvalidStablecoin();
        if (newStableCoinAddress == address(0)) revert InvalidAddress();
        stableCoinAddress = newStableCoinAddress;
        emit StableCoinAddressChanged(newStableCoinAddress, msg.sender);
    }
    
}
