INSERT INTO sources (source_hash, source_hash_keccak, content, created_at, updated_at, created_by, updated_by) VALUES ('\xaff3130ce8058065c2d8c397d5bcd6599889324eed31e040ecee722d4caed33d', '\xad126edcd1216c38aa4906d82d8387db95f58fc1aaaa35d904617ec01952059b', '// SPDX-License-Identifier: MIT
