INSERT INTO sources (source_hash, source_hash_keccak, content, created_at, updated_at, created_by, updated_by) VALUES ('\xb0ef192fc1241cf874de0811a85654935c36ef7339f2f66ca75262d31565ba8e', '\xb3d46284534eb99061d4c79968c2d0420b63a6649d118ef2ea3608396b85de3f', 'pragma solidity ^0.8.4;

library ModexpPrecompile {
    /**
     * @dev Computes (base ^ exponent) % modulus over big numbers.
     */
    function modexp(
        bytes memory base,
        bytes memory exponent,
        bytes memory modulus
    ) internal view returns (bool success, bytes memory output) {
        bytes memory input = abi.encodePacked(
            uint256(base.length),
            uint256(exponent.length),
            uint256(modulus.length),
            base,
            exponent,
            modulus
        );

        output = new bytes(modulus.length);

        assembly {
            success := staticcall(
                gas(),
                5,
                add(input, 32),
                mload(input),
                add(output, 32),
                mload(modulus)
            )
        }
    }
}
