INSERT INTO sources (source_hash, source_hash_keccak, content, created_at, updated_at, created_by, updated_by) VALUES ('\xe5715f25eb09d42846c71a3dadef8fa85d475b9adb21ebe5afb228b00298e401', '\x5d87f1961161fdf13f582847b24fcff27f1f6508f4380300278fbd58c0253c66', '// SPDX-License-Identifier: MIT
pragma solidity ^0.8.9;

function isContract(address account) view returns (bool) {
    return account.code.length > 0;
}

function freeDelegateCall(
    address target,
    bytes memory data
) returns (bytes memory) {
    (, bytes memory returndata) = target.delegatecall(data);
    return returndata;
}
